{"command":"python3 - << 'PY'
import pty, os, subprocess, time, select, sys, signal, termios, struct, fcntl

def run_with_pty(argv, inputs=None, width=80, height=24, timeout=2):
    # inputs: list of bytes to send with delays
    # Returns output
    pid, fd = pty.fork()
    if pid == 0:
        # child
        # set winsize
        # TIOCSWINSZ
        try:
            import fcntl, termios
            winsz = struct.pack("HHHH", height, width, 0, 0)
            fcntl.ioctl(pty.STDOUT_FILENO, termios.TIOCSWINSZ, winsz)
        except Exception as e:
            pass
        os.execvp(argv[0], argv)
    else:
        # parent
        output = b""
        start = time.time()
        # give child time
        # We'll attempt to read until timeout or child exits, and send inputs if any
        if inputs:
            # inputs: list of (delay, data)
            for delay, data in inputs:
                time.sleep(delay)
                # try to read available before write
                while True:
                    r, _, _ = select.select([fd], [], [], 0.1)
                    if not r:
                        break
                    try:
                        chunk = os.read(fd, 4096)
                        if not chunk:
                            break
                        output += chunk
                    except OSError:
                        break
                os.write(fd, data)
        # read remaining
        while time.time() - start < timeout:
            r, _, _ = select.select([fd], [], [], 0.2)
            if r:
                try:
                    chunk = os.read(fd, 8192)
                    if not chunk:
                        break
                    output += chunk
                except OSError:
                    break
            else:
                # check if child alive
                try:
                    pid2, status = os.waitpid(pid, os.WNOHANG)
                    if pid2 != 0:
                        break
                except ChildProcessError:
                    break
        # try kill child
        try:
            os.kill(pid, signal.SIGKILL)
        except: pass
        try:
            os.waitpid(pid, 0)
        except: pass
        try:
            os.close(fd)
        except: pass
        return output

out = run_with_pty(["./executable", "--help"])
print(out.decode(errors='ignore'))

# Now try normal editor with empty buffer, capture initial screen, then send Ctrl-Q to quit
out = run_with_pty(["./executable"], inputs=[(0.5, b'\x11')], timeout=3)  # Ctrl-Q
print("----EMPTY START----")
print(out.decode('utf-8', errors='ignore')[:10000])
print("----END----")
