                    let _ = std::io::stdout().flush();
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
            // Also try open file to get permission errors
            match fs::File::open(path) {
                Ok(_) => {},
                Err(e) => {
                    print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                    use std::io::Write;
                    let _ = std::io::stdout().flush();
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        } else {
            // File doesn't exist, check if parent directory exists and is writable? Not needed, save will fail later.
            // Also check if path is something that would be directory? Already not exists.
        }
    }

    // If we reach here, we would start editor. For now stub.
