use std::env;
use std::io;
use std::os::raw::{c_int, c_uint};
use std::fs;
use std::process;

const STDOUT_FD: c_int = 1;

#[repr(C)]
#[derive(Debug, Default, Clone, Copy)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

unsafe extern "C" {
    fn ioctl(fd: c_int, request: c_uint, ...) -> c_int;
}

fn get_winsize() -> io::Result<Winsize> {
    unsafe {
        let mut ws = Winsize::default();
        let ret = ioctl(STDOUT_FD, 0x5413, &mut ws);
        if ret == -1 {
            Err(io::Error::last_os_error())
        } else {
            Ok(ws)
        }
    }
}

const VERSION: &str = "0.4.3";

fn print_help(arg0: &str) {
    println!("{}: A tiny UTF-8 terminal text editor", arg0);
    println!();
    println!("Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.");
