use std::os::raw::{c_int, c_uint};
use std::fs;
use std::process;

const STDOUT_FD: c_int = 1;
const STDIN_FD: c_int = 0;

#[repr(C)]
#[derive(Debug, Default, Clone, Copy)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

unsafe extern "C" {
    fn ioctl(fd: c_int, request: c_uint, ...) -> c_int;
    fn tcgetattr(fd: c_int, termios: *mut Termios) -> c_int;
    fn tcsetattr(fd: c_int, optional_actions: c_int, termios: *const Termios) -> c_int;
    fn read(fd: c_int, buf: *mut u8, count: usize) -> isize;
}

#[repr(C)]
#[derive(Clone, Copy, Debug)]
struct Termios {
    c_iflag: c_uint,
    c_oflag: c_uint,
    c_cflag: c_uint,
    c_lflag: c_uint,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: c_uint,
    c_ospeed: c_uint,
}

const VERSION: &str = "0.4.3";

fn print_help(arg0: &str) {
    println!("{}: A tiny UTF-8 terminal text editor", arg0);
    println!();
    println!("Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.");
    println!("Specify file paths to edit as a command argument or run without argument to");
    println!("start to write a new text.");
    println!("Help can show up with key mapping Ctrl-?.");
    println!();
    println!("Usage:");
    println!("    {} [options] [FILES...]", arg0);
    println!();
    println!("Mappings:");
    println!("    Ctrl-Q                        : Quit");
    println!("    Ctrl-S                        : Save to file");
    println!("    Ctrl-O                        : Open text buffer");
    println!("    Ctrl-X                        : Next text buffer");
    println!("    Alt-X                         : Previous text buffer");
    println!("    Ctrl-P or UP                  : Move cursor up");
    println!("    Ctrl-N or DOWN                : Move cursor down");
    println!("    Ctrl-F or RIGHT               : Move cursor right");
    println!("    Ctrl-B or LEFT                : Move cursor left");
    println!("    Ctrl-A or Alt-LEFT or HOME    : Move cursor to head of line");
    println!("    Ctrl-E or Alt-RIGHT or END    : Move cursor to end of line");
    println!("    Ctrl-[ or Ctrl-V or PAGE DOWN : Next page");
    println!("    Ctrl-] or Alt-V or PAGE UP    : Previous page");
    println!("    Alt-F or Ctrl-RIGHT           : Move cursor to next word");
    println!("    Alt-B or Ctrl-LEFT            : Move cursor to previous word");
    println!("    Alt-N or Ctrl-DOWN            : Move cursor to next paragraph");
    println!("    Alt-P or Ctrl-UP              : Move cursor to previous paragraph");
    println!("    Alt-<                         : Move cursor to top of file");
    println!("    Alt->                         : Move cursor to bottom of file");
    println!("    Ctrl-H or BACKSPACE           : Delete character");
    println!("    Ctrl-D or DELETE              : Delete next character");
    println!("    Ctrl-W                        : Delete a word");
    println!("    Ctrl-J                        : Delete until head of line");
    println!("    Ctrl-K                        : Delete until end of line");
    println!("    Ctrl-U                        : Undo last change");
    println!("    Ctrl-R                        : Redo last undo change");
    println!("    Ctrl-G                        : Search text");
    println!("    Ctrl-M                        : New line");
    println!("    Ctrl-L                        : Refresh screen");
    println!("    Ctrl-?                        : Show this help");
    println!();
    println!("Options:");
    println!("    -v, --version       Print version");
    println!("    -h, --help          Print this help");
    println!();
}

fn get_winsize() -> io::Result<Winsize> {
    unsafe {
        let mut ws = Winsize::default();
        let ret = ioctl(STDOUT_FD, 0x5413, &mut ws);
        if ret == -1 {
            Err(io::Error::last_os_error())
        } else {
            Ok(ws)
        }
    }
}

// File reading logic
fn read_file_rows(path: &str) -> io::Result<Vec<String>> {
    let data = fs::read(path)?;
    if data.is_empty() {
        return Ok(vec![]);
    }
    // Check if valid utf-8? Original handles utf-8, but what if invalid? It should handle? Let's try to decode lossily? But original likely reads as utf-8 and may error? For binary file with invalid utf-8 we tested earlier with \xff\xfe\xfd\n – let's see what happens: original showed something? Our earlier binary test printed empty? We should test again with more careful capture. But for now we will read as utf-8 lossily or error? The original probably reads file as bytes and interprets as utf-8? The LICENSE says utf-8 text editor. If file contains invalid utf-8, maybe it still shows replacement? Let's just read as utf-8 and if invalid, treat as lossy? Simpler: use String::from_utf8_lossy? That would not error.
    // But we need to replicate original's handling: try to read as utf-8, if invalid, maybe it still loads? Let's assume lossy.
    let text = String::from_utf8_lossy(&data);
    // Split by '\n'
    let mut lines: Vec<String> = text.split('\n').map(|s| s.to_string()).collect();
    // If file ends with '\n', split will have trailing empty. Remove last if file ends with '\n'
    if text.ends_with('\n') {
        if !lines.is_empty() {
            lines.pop();
        }
    }
    // If original empty, we already returned []
    Ok(lines)
}

// Simple editor stub for now
fn main() {
    let args: Vec<String> = env::args().collect();
    let arg0 = args.get(0).map(|s| s.as_str()).unwrap_or("./executable");

    // Parse CLI
    let mut files: Vec<String> = Vec::new();
    let mut version_flag = false;
    let mut help_flag = false;
    let mut end_of_options = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if end_of_options {
            files.push(arg.clone());
        } else if arg == "--" {
            end_of_options = true;
        } else if arg == "-" {
            files.push(arg.clone());
        } else if arg.starts_with("--") {
            if arg == "--version" {
                version_flag = true;
            } else if arg == "--help" {
                help_flag = true;
            } else {
                let name = &arg[2..];
                eprintln!("Error: Unrecognized option: '{}'. Please see --help for more details", name);
                process::exit(1);
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            for ch in arg[1..].chars() {
                if ch == 'v' {
                    version_flag = true;
                } else if ch == 'h' {
                    help_flag = true;
                } else {
                    eprintln!("Error: Unrecognized option: '{}'. Please see --help for more details", ch);
                    process::exit(1);
                }
            }
        } else {
            files.push(arg.clone());
        }
        i += 1;
    }

    if version_flag {
        println!("{}", VERSION);
        return;
    }
    if help_flag {
        print_help(arg0);
        return;
    }

    // Check winsize
    let ws = match get_winsize() {
        Ok(ws) => ws,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    // Validate files
    for fname in &files {
        let path = std::path::Path::new(fname);
        match fs::metadata(path) {
            Ok(meta) => {
                if meta.is_dir() {
                    let err = io::Error::from_raw_os_error(21);
                    print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                    let _ = io::stdout().flush();
                    eprintln!("Error: {}", err);
                    process::exit(1);
                }
                match fs::File::open(path) {
                    Ok(_) => {},
                    Err(e) => {
                        print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                        let _ = io::stdout().flush();
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
            },
            Err(e) => {
                if e.kind() != io::ErrorKind::NotFound {
                    print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                    let _ = io::stdout().flush();
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
    }

    // Load buffers
    // For each file, read rows
    struct Buffer {
        filename: Option<String>,
        rows: Vec<String>,
        dirty: bool,
    }

    let mut buffers: Vec<Buffer> = Vec::new();
    if files.is_empty() {
        buffers.push(Buffer { filename: None, rows: vec![String::new()], dirty: false });
    } else {
        for fname in files {
            let path = std::path::Path::new(&fname);
            if !path.exists() {
                buffers.push(Buffer { filename: Some(fname.clone()), rows: vec![String::new()], dirty: false });
            } else {
                match read_file_rows(&fname) {
                    Ok(rows) => {
                        buffers.push(Buffer { filename: Some(fname.clone()), rows, dirty: false });
                    },
                    Err(e) => {
                        print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                        let _ = io::stdout().flush();
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
            }
        }
    }

    // For stub, just show first buffer info and quit
    // We will later implement editor loop
    eprintln!("Loaded {} buffers, ws {}x{}", buffers.len(), ws.ws_row, ws.ws_col);
}
