fn enable_raw_mode() -> io::Result<Termios> {
    unsafe {
        let mut orig = std::mem::zeroed::<Termios>();
        if tcgetattr(STDIN_FD, &mut orig) != 0 {
            return Err(io::Error::last_os_error());
        }
        let mut raw = orig;
        raw.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        raw.c_oflag &= !(OPOST);
        raw.c_cflag |= CS8;
        raw.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        raw.c_cc[VMIN] = 0;
        raw.c_cc[VTIME] = 1;
        if tcsetattr(STDIN_FD, TCSANOW, &raw) != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(orig)
    }
}

fn disable_raw_mode(orig: &Termios) {
    unsafe {
        let _ = tcsetattr(STDIN_FD, TCSANOW, orig);
    }
}

// Very simple key reading
fn read_key() -> io::Result<Vec<u8>> {
    let mut buf = [0u8; 32];
    unsafe {
        let n = read(STDIN_FD, buf.as_mut_ptr(), 1);
        if n <= 0 {
            return Ok(vec![]);
        }
        let mut seq = vec![buf[0]];
        if buf[0] == 27 {
            // ESC, try to read more with timeout (we already have VTIME 100ms)
            // Attempt to read up to 10 more bytes, non-blocking due to VTIME
            // Try read up to 3 times?
            for _ in 0..3 {
                let mut extra = [0u8; 16];
                let n2 = read(STDIN_FD, extra.as_mut_ptr(), extra.len());
                if n2 > 0 {
                    seq.extend_from_slice(&extra[..n2 as usize]);
                    // If we see final byte that ends sequence, break?
                    // Simple heuristic: if seq ends with ~ or letter A-Z
                    // We'll continue reading if not yet complete?
                    // For simplicity, read once more if needed
                    if seq.len() >= 2 && seq[1] == b'[' {
                        // CSI, need to read until ~ or A-Z
                        // Already read some, check if last char is in terminator set
                        let last = seq[seq.len()-1];
                        if (b'A'..=b'Z').contains(&last) || (b'a'..=b'z').contains(&last) || last == b'~' {
                            break;
                        }
                        // otherwise continue reading
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
        }
        Ok(seq)
    }
}

