fn main() {
    let args: Vec<String> = env::args().collect();
    let arg0 = args.get(0).map(|s| s.as_str()).unwrap_or("./executable");

    let mut files: Vec<String> = Vec::new();
    let mut version_flag = false;
    let mut help_flag = false;
    let mut end_of_options = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if end_of_options {
            files.push(arg.clone());
        } else if arg == "--" {
            end_of_options = true;
        } else if arg == "-" {
            files.push(arg.clone());
        } else if arg.starts_with("--") {
            if arg == "--version" {
                version_flag = true;
            } else if arg == "--help" {
                help_flag = true;
            } else {
                let name = &arg[2..];
                eprintln!("Error: Unrecognized option: '{}'. Please see --help for more details", name);
                process::exit(1);
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            for ch in arg[1..].chars() {
                if ch == 'v' {
                    version_flag = true;
                } else if ch == 'h' {
                    help_flag = true;
                } else {
                    eprintln!("Error: Unrecognized option: '{}'. Please see --help for more details", ch);
                    process::exit(1);
                }
            }
        } else {
            files.push(arg.clone());
        }
        i += 1;
    }

    if version_flag {
        println!("{}", VERSION);
        return;
    }
    if help_flag {
        print_help(arg0);
        return;
    }

    let ws = match get_winsize() {
        Ok(ws) => ws,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    for fname in &files {
        let path = std::path::Path::new(fname);
        match fs::metadata(path) {
            Ok(meta) => {
                if meta.is_dir() {
                    let err = io::Error::from_raw_os_error(21);
                    print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                    let _ = io::stdout().flush();
                    eprintln!("Error: {}", err);
                    process::exit(1);
                }
                match fs::File::open(path) {
                    Ok(_) => {},
                    Err(e) => {
                        print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                        let _ = io::stdout().flush();
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
            },
            Err(e) => {
                if e.kind() != io::ErrorKind::NotFound {
                    print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                    let _ = io::stdout().flush();
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
    }

    // Load buffers
    let mut buffers: Vec<Buffer> = Vec::new();
    if files.is_empty() {
        buffers.push(Buffer::new(None, vec![String::new()]));
    } else {
        for fname in files {
            let path = std::path::Path::new(&fname);
            if !path.exists() {
                buffers.push(Buffer::new(Some(fname.clone()), vec![String::new()]));
            } else {
                match read_file_rows(&fname) {
                    Ok(rows) => {
                        buffers.push(Buffer::new(Some(fname.clone()), rows));
                    },
                    Err(e) => {
                        print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                        let _ = io::stdout().flush();
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
            }
        }
    }

    // Setup raw mode
    let orig_termios = match enable_raw_mode() {
        Ok(t) => t,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    // Enter alt screen
    print!("\x1b[?1049h");
    print!("\x1b[?25l");
    let _ = io::stdout().flush();

    let mut editor = Editor {
        buffers,
        cur_buf: 0,
        screen_rows: ws.ws_row as usize - 2,
        screen_cols: ws.ws_col as usize,
        help: false,
        quit_times: 0,
        status_msg: "Ctrl-? for help".to_string(),
        status_time: std::time::Instant::now(),
    };

    // Draw initial screen
    // We'll manually implement drawing
    {
        let mut stdout = io::stdout();
        // clear screen?
        // Draw rows
        let buf = &editor.buffers[editor.cur_buf];
        for y in 0..editor.screen_rows {
            let row_idx = y;
            write!(stdout, "\x1b[{}H", y+1).unwrap();
            write!(stdout, "\x1b[39;0m").unwrap();
            if row_idx < buf.rows.len() {
                // draw row content
                let line = &buf.rows[row_idx];
                // truncate to screen_cols? For now full
                // Also need to handle tabs: replace tab with 8 spaces?
                let rendered = line.replace('\t', "        ");
                write!(stdout, "{}", rendered).unwrap();
            } else {
                if editor.buffers.len() == 1 && editor.buffers[0].filename.is_none() && editor.buffers[0].rows.len()==1 && editor.buffers[0].rows[0].is_empty() && y == editor.screen_rows/3 {
                    let welcome = format!("Kiro editor -- version {}", VERSION);
                    let padding = (editor.screen_cols - welcome.len())/2;
                    write!(stdout, "\x1b[37m~\x1b[39;0m").unwrap();
                    write!(stdout, "{}{}", " ".repeat(padding-1), welcome).unwrap();
                } else {
                    write!(stdout, "\x1b[37m~\x1b[39;0m").unwrap();
                }
            }
            write!(stdout, "\x1b[K").unwrap();
        }
        // status bar
        let total_buffers = editor.buffers.len();
        let cur = editor.cur_buf + 1;
        let filename = match &editor.buffers[editor.cur_buf].filename {
            Some(f) => f.clone(),
            None => "[No Name]".to_string(),
        };
        let left = format!("\"{}\" - {}/{}", filename, cur, total_buffers);
        let right = {
            let total_rows = editor.buffers[editor.cur_buf].rows.len();
            // For empty file (0 rows) total_rows 0
            format!("plain {}/{}", editor.buffers[editor.cur_buf].cy+1, total_rows)
        };
        let spaces = if editor.screen_cols > left.len() + right.len() {
            editor.screen_cols - left.len() - right.len()
        } else {
            0
        };
        write!(stdout, "\x1b[{}H\x1b[7m{}{}{}\x1b[39;0m", editor.screen_rows+1, left, " ".repeat(spaces), right).unwrap();
        // message bar
        write!(stdout, "\x1b[{}H{}\x1b[K", editor.screen_rows+2, editor.status_msg).unwrap();
        // cursor
        write!(stdout, "\x1b[{};{}H", editor.buffers[editor.cur_buf].cy+1, editor.buffers[editor.cur_buf].cx+1).unwrap();
        write!(stdout, "\x1b[?25h").unwrap();
        stdout.flush().unwrap();
    }

    // Input loop
    loop {
        let key = match read_key() {
            Ok(k) => k,
            Err(_) => continue,
        };
        if key.is_empty() {
            continue;
        }
        // Check Ctrl-Q = 17
        if key.len() == 1 && key[0] == 17 {
            // quit
            let mut dirty = false;
            for b in &editor.buffers {
                if b.dirty {
                    dirty = true;
                    break;
                }
            }
            if dirty && editor.quit_times == 0 {
                editor.quit_times += 1;
                editor.status_msg = "At least one file has unsaved changes! Press ^Q again to quit or ^S to save".to_string();
                // draw message with colors 97m 41m ?
                // We'll redraw message bar
                let mut stdout = io::stdout();
                write!(stdout, "\x1b[?25l").unwrap();
                write!(stdout, "\x1b[{}H\x1b[97m\x1b[41m{}\x1b[39;0m\x1b[K", editor.screen_rows+2, editor.status_msg).unwrap();
                // cursor
                let buf = &editor.buffers[editor.cur_buf];
                write!(stdout, "\x1b[{};{}H", buf.cy+1, buf.cx+1).unwrap();
                write!(stdout, "\x1b[?25h").unwrap();
                stdout.flush().unwrap();
                continue;
            } else {
                break;
            }
        } else if key.len() == 1 && key[0] == 19 {
            // Ctrl-S save
            editor.status_msg = "Save not implemented".to_string();
        } else {
            // For now ignore
            // set status to show key?
            // editor.status_msg = format!("Key {:?}", key);
        }

        // redraw? for now just update message
        let mut stdout = io::stdout();
        write!(stdout, "\x1b[{}H{}\x1b[K", editor.screen_rows+2, editor.status_msg).unwrap();
        let buf = &editor.buffers[editor.cur_buf];
        write!(stdout, "\x1b[{};{}H", buf.cy+1, buf.cx+1).unwrap();
        stdout.flush().unwrap();
    }

    // Exit alt screen
    print!("\x1b[?25l");
    print!("\x1b[?1049l\x1b[H");
    let _ = io::stdout().flush();
    disable_raw_mode(&orig_termios);
}
