fn read_file_rows(path: &str) -> io::Result<Vec<String>> {
    let data = fs::read(path)?;
    if data.is_empty() {
        return Ok(vec![]);
    }
    let text = String::from_utf8_lossy(&data);
    let mut lines: Vec<String> = text.split('\n').map(|s| s.to_string()).collect();
    if text.ends_with('\n') {
        if !lines.is_empty() {
            lines.pop();
        }
    }
    Ok(lines)
}

#[derive(Clone)]
struct Buffer {
    filename: Option<String>,
    rows: Vec<String>,
    dirty: bool,
    cx: usize, // character index (not byte) – for simplicity we'll use byte for ascii, but need char handling eventually
    cy: usize,
    rowoff: usize,
    coloff: usize,
}

impl Buffer {
    fn new(filename: Option<String>, rows: Vec<String>) -> Self {
        Self { filename, rows, dirty: false, cx: 0, cy: 0, rowoff: 0, coloff: 0 }
    }
}

struct Editor {
    buffers: Vec<Buffer>,
    cur_buf: usize,
    screen_rows: usize,
    screen_cols: usize,
    help: bool,
    quit_times: usize,
    status_msg: String,
}

fn enable_raw_mode() -> io::Result<Termios> {
    unsafe {
        let mut orig = std::mem::zeroed::<Termios>();
        if tcgetattr(STDIN_FD, &mut orig) != 0 {
            return Err(io::Error::last_os_error());
        }
        let mut raw = orig;
        raw.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        raw.c_oflag &= !(OPOST);
        raw.c_cflag |= CS8;
        raw.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        raw.c_cc[VMIN] = 0;
        raw.c_cc[VTIME] = 1;
        if tcsetattr(STDIN_FD, TCSANOW, &raw) != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(orig)
    }
}

fn disable_raw_mode(orig: &Termios) {
    unsafe {
        let _ = tcsetattr(STDIN_FD, TCSANOW, orig);
    }
}

fn read_key() -> io::Result<Vec<u8>> {
    let mut buf = [0u8; 1];
    unsafe {
        let n = read(STDIN_FD, buf.as_mut_ptr(), 1);
        if n <= 0 {
            return Ok(vec![]);
        }
        let mut seq = vec![buf[0]];
        if buf[0] == 27 {
            // Try to read more
            for _ in 0..5 {
                let mut extra = [0u8; 16];
                let n2 = read(STDIN_FD, extra.as_mut_ptr(), extra.len());
                if n2 > 0 {
                    seq.extend_from_slice(&extra[..n2 as usize]);
                    // Check if sequence terminated
                    if seq.len() >= 2 {
                        if seq[1] == b'[' || seq[1] == b'O' {
                            // CSI or SS3
                            let last = seq[seq.len()-1];
                            if (b'A'..=b'Z').contains(&last) || (b'a'..=b'z').contains(&last) || last == b'~' {
                                break;
                            }
                            // else continue reading a bit more
                            continue;
                        } else {
                            // Alt+char, just ESC + char, break
                            break;
                        }
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
        }
        Ok(seq)
    }
}

fn should_show_welcome(editor: &Editor) -> bool {
    // Welcome when [No Name] and single empty row? Original shows welcome when filename is None and rows len ==1 and row empty and not help?
    if editor.help {
        return false;
    }
    if editor.buffers.len() != 1 {
        return false;
    }
    let buf = &editor.buffers[editor.cur_buf];
    if buf.filename.is_some() {
        return false;
    }
    if buf.rows.len() == 1 && buf.rows[0].is_empty() {
        return true;
    }
    if buf.rows.is_empty() {
        // Also empty existing file with no name? But we have filename None case with rows [""] not []
        return true;
    }
    false
}

fn draw_screen(editor: &mut Editor) {
    let mut stdout = io::stdout();
    write!(stdout, "\x1b[?25l").unwrap(); // hide cursor

    let screen_rows = editor.screen_rows;
    let screen_cols = editor.screen_cols;

    if editor.help {
        // help mode
        let help_keys = vec![
            ("Ctrl-Q", "Quit"),
            ("Ctrl-S", "Save to file"),
            ("Ctrl-O", "Open text buffer"),
            ("Ctrl-X", "Next text buffer"),
            ("Alt-X", "Previous text buffer"),
            ("Ctrl-P or UP", "Move cursor up"),
            ("Ctrl-N or DOWN", "Move cursor down"),
            ("Ctrl-F or RIGHT", "Move cursor right"),
            ("Ctrl-B or LEFT", "Move cursor left"),
            ("Ctrl-A or Alt-LEFT or HOME", "Move cursor to head of line"),
            ("Ctrl-E or Alt-RIGHT or END", "Move cursor to end of line"),
            ("Ctrl-[ or Ctrl-V or PAGE DOWN", "Next page"),
            ("Ctrl-] or Alt-V or PAGE UP", "Previous page"),
            ("Alt-F or Ctrl-RIGHT", "Move cursor to next word"),
            ("Alt-B or Ctrl-LEFT", "Move cursor to previous word"),
            ("Alt-N or Ctrl-DOWN", "Move cursor to next paragraph"),
            ("Alt-P or Ctrl-UP", "Move cursor to previous paragraph"),
            ("Alt-<", "Move cursor to top of file"),
            ("Alt->", "Move cursor to bottom of file"),
            ("Ctrl-H or BACKSPACE", "Delete character"),
            ("Ctrl-D or DELETE", "Delete next character"),
            ("Ctrl-W", "Delete a word"),
            ("Ctrl-J", "Delete until head of line"),
            ("Ctrl-K", "Delete until end of line"),
            ("Ctrl-U", "Undo last change"),
            ("Ctrl-R", "Redo last undo change"),
            ("Ctrl-G", "Search text"),
            ("Ctrl-M", "New line"),
            ("Ctrl-L", "Refresh screen"),
            ("Ctrl-?", "Show this help"),
        ];
        let total_help = help_keys.len();
        if screen_rows >= total_help {
            let start = (screen_rows - total_help)/2;
            for y in 0..screen_rows {
                write!(stdout, "\x1b[{}H", y+1).unwrap();
                write!(stdout, "\x1b[39;0m").unwrap();
                write!(stdout, "\x1b[K").unwrap();
            }
            for (i, (k, d)) in help_keys.iter().enumerate() {
                let y = start + i;
                write!(stdout, "\x1b[{}H", y+1).unwrap();
                write!(stdout, "       ").unwrap();
                write!(stdout, "\x1b[96m{:<30}\x1b[39;0m: {}", k, d).unwrap();
                write!(stdout, "\x1b[K").unwrap();
            }
        } else {
            for y in 0..screen_rows {
                write!(stdout, "\x1b[{}H", y+1).unwrap();
                write!(stdout, "\x1b[39;0m").unwrap();
                if y < total_help {
                    let (k,d) = &help_keys[y];
                    write!(stdout, "       ").unwrap();
                    write!(stdout, "\x1b[96m{:<30}\x1b[39;0m: {}", k, d).unwrap();
                }
                write!(stdout, "\x1b[K").unwrap();
            }
        }
    } else {
        // normal mode
        let buf = &editor.buffers[editor.cur_buf];
        let welcome = should_show_welcome(editor);
        for y in 0..screen_rows {
            write!(stdout, "\x1b[{}H", y+1).unwrap();
            write!(stdout, "\x1b[39;0m").unwrap();
            if welcome {
                // All rows tilde, but at screen_rows/3 show welcome
                if y == screen_rows/3 {
                    let msg = format!("Kiro editor -- version {}", VERSION);
                    let padding = (screen_cols - msg.len())/2;
                    // padding includes tilde? original: tilde + spaces + msg
                    // spaces = padding -1
                    let spaces = if padding>1 { padding-1 } else { 0 };
                    write!(stdout, "\x1b[37m~\x1b[39;0m{}{}", " ".repeat(spaces), msg).unwrap();
                } else {
                    write!(stdout, "\x1b[37m~\x1b[39;0m").unwrap();
                }
                write!(stdout, "\x1b[K").unwrap();
            } else {
                let file_row = y + buf.rowoff;
                if file_row < buf.rows.len() {
                    let line = &buf.rows[file_row];
                    // Handle rendering with tab expansion and coloff
                    // For now simple: expand tabs to 8 spaces, then apply coloff based on rendered width? But coloff should be based on rendered columns, not byte index.
                    // To simplify, we ignore coloff for now and just truncate line to screen_cols after tab expansion
                    let rendered = line.replace('\t', "        ");
                    // Apply coloff: we need to slice rendered string by display width
                    // Simplified: if coloff > rendered len, show empty, else substring from coloff
                    // For ASCII only, coloff is byte offset? We'll use char count.
                    let start = buf.coloff.min(rendered.len());
                    let truncated: String = rendered.chars().skip(start).take(screen_cols).collect();
                    write!(stdout, "{}", truncated).unwrap();
                    write!(stdout, "\x1b[39;0m\x1b[K").unwrap();
                } else {
                    write!(stdout, "\x1b[37m~\x1b[39;0m\x1b[K").unwrap();
                }
            }
        }
    }

    // status bar
    let buf = &editor.buffers[editor.cur_buf];
    let total_buffers = editor.buffers.len();
    let cur_buf_num = editor.cur_buf + 1;
    let filename = match &buf.filename {
        Some(f) => f.clone(),
        None => "[No Name]".to_string(),
    };
    let left_base = format!("\"{}\" - {}/{}", filename, cur_buf_num, total_buffers);
    let left = if buf.dirty {
        format!("{} (modified)", left_base)
    } else {
        left_base
    };
    let total_rows = buf.rows.len();
    let cur_row = buf.cy + 1;
    // For empty file with 0 rows, cur_row is 1 but total_rows 0, still show 1/0
    let right = format!("plain {}/{}", cur_row, total_rows);
    let spaces = if screen_cols > left.len() + right.len() {
        screen_cols - left.len() - right.len()
    } else {
        0
    };
    write!(stdout, "\x1b[{}H\x1b[7m{}{}{}\x1b[39;0m", screen_rows+1, left, " ".repeat(spaces), right).unwrap();

    // message bar
    write!(stdout, "\x1b[{}H{}\x1b[K", screen_rows+2, editor.status_msg).unwrap();

    // cursor position: need to compute screen cursor x,y
    // For simplicity, hide complexity: just place cursor at current buffer cx,cy relative to rowoff/coloff
    let render_cx = buf.cx - buf.coloff; // This is not correct for tabs and wide chars, but approximation
    let render_cy = buf.cy - buf.rowoff;
    if render_cy < screen_rows {
        write!(stdout, "\x1b[{};{}H", render_cy+1, render_cx+1).unwrap();
    } else {
        write!(stdout, "\x1b[{};{}H", screen_rows+1, 1).unwrap();
    }

    write!(stdout, "\x1b[?25h").unwrap();
    stdout.flush().unwrap();
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let arg0 = args.get(0).map(|s| s.as_str()).unwrap_or("./executable");

    let mut files: Vec<String> = Vec::new();
    let mut version_flag = false;
    let mut help_flag = false;
    let mut end_of_options = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if end_of_options {
            files.push(arg.clone());
        } else if arg == "--" {
            end_of_options = true;
        } else if arg == "-" {
            files.push(arg.clone());
        } else if arg.starts_with("--") {
            if arg == "--version" {
                version_flag = true;
            } else if arg == "--help" {
                help_flag = true;
            } else {
                let name = &arg[2..];
                eprintln!("Error: Unrecognized option: '{}'. Please see --help for more details", name);
                process::exit(1);
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            for ch in arg[1..].chars() {
                if ch == 'v' {
                    version_flag = true;
                } else if ch == 'h' {
                    help_flag = true;
                } else {
                    eprintln!("Error: Unrecognized option: '{}'. Please see --help for more details", ch);
                    process::exit(1);
                }
            }
        } else {
            files.push(arg.clone());
        }
        i += 1;
    }

    if version_flag {
        println!("{}", VERSION);
        return;
    }
    if help_flag {
        print_help(arg0);
        return;
    }

    let ws = match get_winsize() {
        Ok(ws) => ws,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    for fname in &files {
        let path = std::path::Path::new(fname);
        match fs::metadata(path) {
            Ok(meta) => {
                if meta.is_dir() {
                    let err = io::Error::from_raw_os_error(21);
                    print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                    let _ = io::stdout().flush();
                    eprintln!("Error: {}", err);
                    process::exit(1);
                }
                match fs::File::open(path) {
                    Ok(_) => {},
                    Err(e) => {
                        print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                        let _ = io::stdout().flush();
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
            },
            Err(e) => {
                if e.kind() != io::ErrorKind::NotFound {
                    print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                    let _ = io::stdout().flush();
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
    }

    let mut buffers: Vec<Buffer> = Vec::new();
    if files.is_empty() {
        buffers.push(Buffer::new(None, vec![String::new()]));
    } else {
        for fname in files {
            let path = std::path::Path::new(&fname);
            if !path.exists() {
                buffers.push(Buffer::new(Some(fname.clone()), vec![String::new()]));
            } else {
                match read_file_rows(&fname) {
                    Ok(rows) => {
                        buffers.push(Buffer::new(Some(fname.clone()), rows));
                    },
                    Err(e) => {
                        print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                        let _ = io::stdout().flush();
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
            }
        }
    }

    let orig_termios = match enable_raw_mode() {
        Ok(t) => t,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    print!("\x1b[?1049h");
    let _ = io::stdout().flush();

    let mut editor = Editor {
        buffers,
        cur_buf: 0,
        screen_rows: ws.ws_row as usize - 2,
        screen_cols: ws.ws_col as usize,
        help: false,
        quit_times: 0,
        status_msg: "Ctrl-? for help".to_string(),
    };

    draw_screen(&mut editor);

    loop {
        let key = match read_key() {
            Ok(k) => k,
            Err(_) => continue,
        };
        if key.is_empty() {
            continue;
        }
        let mut dirty_check = false;
        if key.len() == 1 {
            match key[0] {
                17 => { // Ctrl-Q
                    let mut any_dirty = false;
                    for b in &editor.buffers {
                        if b.dirty {
                            any_dirty = true;
                            break;
                        }
                    }
                    if any_dirty && editor.quit_times == 0 {
                        editor.quit_times += 1;
                        editor.status_msg = "At least one file has unsaved changes! Press ^Q again to quit or ^S to save".to_string();
                        // redraw message with red background
                        let mut stdout = io::stdout();
                        write!(stdout, "\x1b[?25l").unwrap();
                        write!(stdout, "\x1b[{}H\x1b[97m\x1b[41m{}\x1b[39;0m\x1b[K", editor.screen_rows+2, editor.status_msg).unwrap();
                        let buf = &editor.buffers[editor.cur_buf];
                        write!(stdout, "\x1b[{};{}H", buf.cy - buf.rowoff +1, buf.cx - buf.coloff +1).unwrap();
                        write!(stdout, "\x1b[?25h").unwrap();
                        stdout.flush().unwrap();
                        continue;
                    } else {
                        break;
                    }
                },
                31 => { // Ctrl-? 0x1f is Ctrl-? (since ? is 0x3f, Ctrl masks 0x1f)
                    editor.help = !editor.help;
                    editor.status_msg = if editor.help { "".to_string() } else { "Ctrl-? for help".to_string() };
                    draw_screen(&mut editor);
                    continue;
                },
                _ => {}
            }
        }
        // For other keys, reset quit_times
        if key.len() == 1 && key[0] != 17 {
            editor.quit_times = 0;
        }
        draw_screen(&mut editor);
    }

    print!("\x1b[?25l");
    print!("\x1b[?1049l\x1b[H");
    let _ = io::stdout().flush();
    disable_raw_mode(&orig_termios);
}
