    fn ioctl(fd: c_int, request: c_uint, ...) -> c_int;
    fn tcgetattr(fd: c_int, termios: *mut Termios) -> c_int;
    fn tcsetattr(fd: c_int, optional_actions: c_int, termios: *const Termios) -> c_int;
    fn read(fd: c_int, buf: *mut u8, count: usize) -> isize;
}

const VERSION: &str = "0.4.3";
const TIOCGWINSZ: c_uint = 0x5413;
const TCSANOW: c_int = 0;
const VMIN: usize = 6;
const VTIME: usize = 5;

const BRKINT: c_uint = 0o0000002;
const ICRNL: c_uint = 0o0000400;
const INPCK: c_uint = 0o0000020;
const ISTRIP: c_uint = 0o0000040;
const IXON: c_uint = 0o0002000;
const OPOST: c_uint = 0o0000001;
const ECHO: c_uint = 0o0000010;
const ICANON: c_uint = 0o0000002;
const IEXTEN: c_uint = 0o00100000;
const ISIG: c_uint = 0o0000001;
const CS8: c_uint = 0o0000060;

fn get_winsize() -> io::Result<Winsize> {
    unsafe {
        let mut ws = Winsize::default();
        let ret = ioctl(STDOUT_FD, TIOCGWINSZ, &mut ws);
        if ret == -1 {
            Err(io::Error::last_os_error())
        } else {
            Ok(ws)
        }
    }
}

