fn read_file_rows(path: &str) -> io::Result<Vec<String>> {
    let data = fs::read(path)?;
    if data.is_empty() { return Ok(vec![]); }
    let text = String::from_utf8_lossy(&data);
    let mut lines: Vec<String> = text.split('\n').map(|s| s.to_string()).collect();
    if text.ends_with('\n') { if !lines.is_empty() { lines.pop(); } }
    Ok(lines)
}

#[derive(Clone)]
struct Buffer {
    filename: Option<String>,
    rows: Vec<String>,
    dirty: bool,
    cx: usize,
    cy: usize,
    rowoff: usize,
    coloff: usize,
}

impl Buffer {
    fn new(filename: Option<String>, rows: Vec<String>) -> Self {
        Self { filename, rows, dirty: false, cx:0, cy:0, rowoff:0, coloff:0 }
    }
}

struct Editor {
    buffers: Vec<Buffer>,
    cur_buf: usize,
    screen_rows: usize,
    screen_cols: usize,
    help: bool,
    quit_times: usize,
    status_msg: String,
}

fn enable_raw_mode() -> io::Result<Termios> {
    unsafe {
        let mut orig = std::mem::zeroed::<Termios>();
        if tcgetattr(STDIN_FD, &mut orig) != 0 { return Err(io::Error::last_os_error()); }
        let mut raw = orig;
        raw.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        raw.c_oflag &= !(OPOST);
        raw.c_cflag |= CS8;
        raw.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        raw.c_cc[VMIN]=0;
        raw.c_cc[VTIME]=1;
        if tcsetattr(STDIN_FD, TCSANOW, &raw)!=0 { return Err(io::Error::last_os_error()); }
        Ok(orig)
    }
}
fn disable_raw_mode(orig: &Termios) { unsafe { let _ = tcsetattr(STDIN_FD, TCSANOW, orig); } }

fn read_key() -> io::Result<Vec<u8>> {
    let mut buf = [0u8; 1];
    unsafe {
        let n = read(STDIN_FD, buf.as_mut_ptr(), 1);
        if n <=0 { return Ok(vec![]); }
        let mut seq = vec![buf[0]];
        if buf[0]==27 {
            for _ in 0..5 {
                let mut extra = [0u8; 16];
                let n2 = read(STDIN_FD, extra.as_mut_ptr(), extra.len());
                if n2>0 {
                    seq.extend_from_slice(&extra[..n2 as usize]);
                    if seq.len()>=2 {
                        if seq[1]==b'[' || seq[1]==b'O' {
                            let last = seq[seq.len()-1];
                            if (b'A'..=b'Z').contains(&last) || (b'a'..=b'z').contains(&last) || last==b'~' { break; }
                            continue;
                        } else { break; }
                    } else { break; }
                } else { break; }
            }
        }
        Ok(seq)
    }
}

fn should_show_welcome(editor: &Editor) -> bool {
    if editor.help { return false; }
    if editor.buffers.len()!=1 { return false; }
    let buf = &editor.buffers[editor.cur_buf];
    if buf.filename.is_some() { return false; }
    if buf.rows.len()==1 && buf.rows[0].is_empty() { return true; }
    if buf.rows.is_empty() { return true; }
    false
}

