#[derive(Debug, PartialEq)]
enum Key {
    Ctrl(u8), // 0-31
    Char(char),
    Alt(char),
    ArrowUp,
    ArrowDown,
    ArrowLeft,
    ArrowRight,
    Home,
    End,
    PageUp,
    PageDown,
    Delete,
    Backspace, // 127 or 8
    Esc,
    Unknown,
}

fn parse_key(seq: &[u8]) -> Key {
    if seq.is_empty() { return Key::Unknown; }
    if seq.len()==1 {
        let b = seq[0];
        if b == 27 { return Key::Esc; }
        if b == 127 { return Key::Backspace; }
        if b < 32 {
            return Key::Ctrl(b);
        }
        if b >= 32 && b < 127 {
            return Key::Char(b as char);
        }
        // high byte part of utf-8? We'll try to decode as utf-8 char if sequence is valid utf-8 and length>1? But our read_key reads ESC sequences separately. For normal utf-8 multi-byte, first byte will be >=192, and following bytes will be continuation. Our read_key reads only 1 byte for non-ESC, so multi-byte utf-8 will be split. We need to handle reading more bytes for utf-8.
        // For now, treat as Unknown
        return Key::Unknown;
    } else {
        // ESC sequence
        if seq[0]==27 {
            if seq.len()==2 {
                // Alt + char
                let ch = seq[1] as char;
                // Alt-char mappings: we should handle lower case only? We'll return Alt
                return Key::Alt(ch);
            } else if seq[1]==b'[' || seq[1]==b'O' {
                // CSI
                // Look at sequence content
                let s = String::from_utf8_lossy(seq);
                // Arrow keys
                match s.as_ref() {
                    "\x1b[A" => return Key::ArrowUp,
                    "\x1b[B" => return Key::ArrowDown,
                    "\x1b[C" => return Key::ArrowRight,
                    "\x1b[D" => return Key::ArrowLeft,
                    "\x1b[H" => return Key::Home,
                    "\x1b[F" => return Key::End,
                    "\x1b[1~" => return Key::Home,
                    "\x1b[4~" => return Key::End,
                    "\x1b[3~" => return Key::Delete,
                    "\x1b[5~" => return Key::PageUp,
                    "\x1b[6~" => return Key::PageDown,
                    _ => {
                        // Check for Ctrl/Alt + arrows: format \x1b[1;5A etc
                        if s == "\x1b[1;5A" { return Key::Ctrl(16); } // Ctrl-P? Actually Ctrl-UP should be paragraph prev, but we map to Ctrl-P handling later
                        if s == "\x1b[1;5B" { return Key::Ctrl(14); } // Ctrl-N
                        if s == "\x1b[1;5C" { return Key::Alt('f'); } // Alt-F or Ctrl-RIGHT next word
                        if s == "\x1b[1;5D" { return Key::Alt('b'); } // Alt-B or Ctrl-LEFT prev word
                        if s == "\x1b[1;3C" { return Key::Ctrl(5); } // Alt-RIGHT? Actually Alt-RIGHT is end of line, mapping: Ctrl-E or Alt-RIGHT or END. So we can map to Ctrl-E
                        if s == "\x1b[1;3D" { return Key::Ctrl(1); } // Alt-LEFT => head
                        // For generic, return Unknown
                        return Key::Unknown;
                    }
                }
            } else {
                return Key::Unknown;
            }
        }
        Key::Unknown
    }
}

// Handle reading UTF-8 from stdin in raw mode: since we read one byte at a time, we need to accumulate bytes for multi-byte char.
// We'll implement a function that reads a key and if it's start of UTF-8 multi-byte, read more.

fn read_input() -> io::Result<Key> {
    // This will read bytes and try to parse as Key + UTF-8 char
    let mut buf = [0u8; 1];
    unsafe {
        let n = read(STDIN_FD, buf.as_mut_ptr(), 1);
        if n <=0 { return Ok(Key::Unknown); }
        let b = buf[0];
        if b == 27 {
            // ESC sequence
            let mut seq = vec![b];
            for _ in 0..6 {
                let mut extra = [0u8; 32];
                let n2 = read(STDIN_FD, extra.as_mut_ptr(), extra.len());
                if n2>0 {
                    seq.extend_from_slice(&extra[..n2 as usize]);
                    if seq.len()>=2 {
                        if seq[1]==b'[' || seq[1]==b'O' {
                            let last = seq[seq.len()-1];
                            if (b'A'..=b'Z').contains(&last) || (b'a'..=b'z').contains(&last) || last==b'~' { break; }
                            continue;
                        } else { break; }
                    } else { break; }
                } else { break; }
            }
            return Ok(parse_key(&seq));
        }
        if b == 127 { return Ok(Key::Backspace); }
        if b < 32 {
            return Ok(Key::Ctrl(b));
        }
        if b < 0x80 {
            return Ok(Key::Char(b as char));
        }
        // UTF-8 multi-byte: need to read continuation bytes
        // Determine length by leading bits
        let mut utf8_bytes = vec![b];
        let mut needed = 0;
        if b & 0b11100000 == 0b11000000 { needed =1; }
        else if b & 0b11110000 == 0b11100000 { needed =2; }
        else if b & 0b11111000 == 0b11110000 { needed =3; }
        else { return Ok(Key::Unknown); }
        for _ in 0..needed {
            let mut extra = [0u8;1];
            let n2 = read(STDIN_FD, extra.as_mut_ptr(),1);
            if n2>0 { utf8_bytes.push(extra[0]); } else { break; }
        }
        let s = String::from_utf8_lossy(&utf8_bytes);
        if let Some(ch) = s.chars().next() {
            return Ok(Key::Char(ch));
        }
        return Ok(Key::Unknown);
    }
}

