                            editor.prompt = Some(Prompt::Save(input, cx));
                            draw_screen(&mut editor);
                            continue;
                        },
                        Key::Backspace => {
                            if cx>0 {
                                input.remove(cx-1);
                                cx-=1;
                            }
                            editor.prompt = Some(Prompt::Save(input, cx));
                            draw_screen(&mut editor);
                            continue;
                        },
                        Key::Ctrl(8) | Key::Ctrl(2) | Key::ArrowLeft => {
                            if cx>0 { cx-=1; }
                            editor.prompt = Some(Prompt::Save(input, cx));
                            draw_screen(&mut editor);
                            continue;
                        },
                        Key::Ctrl(6) | Key::ArrowRight => {
                            if cx < input.len() { cx+=1; }
                            editor.prompt = Some(Prompt::Save(input, cx));
                            draw_screen(&mut editor);
                            continue;
                        },
                        _ => {
                            // Enter saves?
                            if let Key::Ctrl(13) | Key::Ctrl(10) = key {
                                // Actually search for Enter key: we parse Ctrl-M as 13
                            }
                            // For simplicity, treat Char '\r' or '\n' as Enter
                            // Our Key parsing doesn't handle Enter as Ctrl-M? Ctrl-M is 13
                            // We'll handle below
                        }
                    }
                    // Check for Enter (Ctrl-M = 13)
                    if let Key::Ctrl(13) = key {
                        // Save
                        // If input empty, error? Original shows "Empty name"? But for Save As, empty name? Let's see original Save as prompt when empty? It always has hint, but if you press Enter with empty input, what happens? Likely does nothing or shows error?
                        // For now, if input empty, cancel?
                        if input.is_empty() {
                            editor.status_msg = "Canceled".to_string();
                            editor.prompt = None;
                            draw_screen(&mut editor);
                            continue;
                        }
                        // Set buffer filename to input and save
                        let cur = editor.cur_buf;
                        editor.buffers[cur].filename = Some(input.clone());
                        // Try save
                        match editor.buffers[cur].save() {
                            Ok(bytes) => {
                                editor.status_msg = format!("{} bytes written to {}", bytes, input);
                                editor.prompt = None;
                                draw_screen(&mut editor);
                            },
                            Err(e) => {
                                editor.status_msg = format!("Can't save! {}", e);
                                editor.prompt = Some(Prompt::Save(input, cx));
                                draw_screen(&mut editor);
                            }
                        }
                        continue;
                    }
                    // Put back prompt if not handled
                    editor.prompt = Some(Prompt::Save(input, cx));
                    draw_screen(&mut editor);
                    continue;
                },
                _ => {
                    editor.prompt = Some(prompt);
                }
            }
        }

        draw_screen(&mut editor);
    }

    print!("\x1b[?25l\x1b[?1049l\x1b[H"); let _=io::stdout().flush();
    disable_raw_mode(&orig_termios);
}
