fn read_file_rows(path: &str) -> io::Result<Vec<String>> {
    let data = fs::read(path)?;
    if data.is_empty() { return Ok(vec![]); }
    // Validate UTF-8
    let text = match String::from_utf8(data) {
        Ok(s) => s,
        Err(_) => {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "stream did not contain valid UTF-8"));
        }
    };
    let mut lines: Vec<String> = text.split('\n').map(|s| s.to_string()).collect();
    if text.ends_with('\n') {
        if !lines.is_empty() { lines.pop(); }
    }
    Ok(lines)
}

#[derive(Clone, Debug)]
struct Buffer {
    filename: Option<String>,
    rows: Vec<String>,
    dirty: bool,
    cx: usize, // char index
    cy: usize,
    rowoff: usize,
    coloff: usize,
    // For vertical movement, desired cx column (rendered)
    // For undo
    undo_stack: Vec<Snapshot>,
    redo_stack: Vec<Snapshot>,
}

#[derive(Clone, Debug)]
struct Snapshot {
    rows: Vec<String>,
    cx: usize,
    cy: usize,
}

impl Buffer {
    fn new(filename: Option<String>, rows: Vec<String>) -> Self {
        Self { filename, rows, dirty:false, cx:0, cy:0, rowoff:0, coloff:0, undo_stack: Vec::new(), redo_stack: Vec::new() }
    }

    fn filetype(&self) -> &'static str {
        if let Some(fname) = &self.filename {
            // extract extension
            if let Some(dot) = fname.rfind('.') {
                let ext = &fname[dot+1..];
                match ext {
                    "c" | "h" => return "c",
                    "cpp" | "hpp" | "cc" => return "c++",
                    "rs" => return "rust",
                    "py" => return "python",
                    "js" => return "javascript",
                    "go" => return "go",
                    _ => {}
                }
            }
        }
        "plain"
    }

    fn save(&mut self) -> io::Result<usize> {
        // save logic: if filename None, should not be called; but for safety
        let fname = match &self.filename {
            Some(f) => f.clone(),
            None => return Err(io::Error::new(io::ErrorKind::Other, "No filename")),
        };
        // Write rows each with \n, except if rows empty => 0 bytes
        let mut content = String::new();
        for row in &self.rows {
            content.push_str(row);
            content.push('\n');
        }
        // Special case: if rows empty, we write nothing (0 bytes), not "\n"
        // Our content construction for empty rows would be "" (since loop zero), which is correct for empty file
        // For buffer with one empty row "", content would be "\n" (1 byte) – matches observed
        // But note: if rows is [""] (one empty), loop one iteration -> "" + "\n" = "\n"
        // If rows is [] -> "" (0 bytes)
        // If rows is ["a"] -> "a\n" (2 bytes)
        // This matches earlier observed.
        fs::write(&fname, content.as_bytes())?;
        self.dirty = false;
        Ok(content.len())
    }

    fn push_undo(&mut self) {
        let snap = Snapshot { rows: self.rows.clone(), cx: self.cx, cy: self.cy };
        self.undo_stack.push(snap);
        self.redo_stack.clear();
    }

    fn push_undo_if_needed(&mut self, is_insert: bool) {
        // Simplified grouping: we will push undo for each distinct operation, but grouping consecutive inserts without movement?
        // For now, push every change (not grouping) – will cause multiple undos for "hello" typing, not matching original which groups.
        // To attempt grouping, we need more logic. Let's implement simple grouping: if last undo snapshot is similar and operation is insert char and previous operation was also insert char at adjacent position, we don't push new snapshot, but update? Actually we need to push before first insertion of a sequence.
        // For simplicity, we will push undo only once before a sequence of inserts that are contiguous.
        // We'll handle in insert_char: if undo_stack empty or last operation was not insert, push. Else don't push? But need to track.
        // To keep simple, we push on each char for now – may not match original but at least works.
        self.push_undo();
    }
}

// Unicode width helpers (very simplified)
fn is_wide(c: char) -> bool {
    let cp = c as u32;
    // Rough ranges for wide characters: CJK, etc.
    // This is not complete but enough for testing Japanese and emoji
    // Use simple heuristic: if cp >= 0x1100 and (cp <= 0x115F or cp == 0x2329 or cp == 0x232A or (0x2E80..=0xA4CF).contains(&cp) or (0xAC00..=0xD7A3).contains(&cp) or (0xF900..=0xFAFF).contains(&cp) or (0xFE10..=0xFE19).contains(&cp) or (0xFE30..=0xFE6F).contains(&cp) or (0xFF00..=0xFF60).contains(&cp) or (0xFFE0..=0xFFE6).contains(&cp) or (0x20000..=0x2FFFD).contains(&cp) or (0x30000..=0x3FFFD).contains(&cp) or cp >= 0x1F300 )
    // Simplified: treat any non-ASCII as wide if it is not latin etc. For our tests, Japanese and emoji are wide, so return true for cp > 0x7F except some?
    // We'll check common wide: if cp > 0x7F, we consider wide if it's not in latin extended? Let's just treat any char with cp >= 0x1100 as wide, except we also need to treat many symbols as wide? For simplicity, treat all non-ASCII as width 2 except for combining? This will cause ascii width 1, others width 2.
    // This matches earlier: "あ" width 2, "🎉" width 2.
    cp > 0x7F
}

fn char_display_width(c: char, col: usize) -> usize {
    if c == '\t' {
        8 - (col % 8)
    } else if is_wide(c) {
        2
    } else {
        1
    }
}

