                    write!(out, "\x1b[37m~\x1b[39;0m{}{}\x1b[K", " ".repeat(spaces), msg).unwrap();
                } else {
                    write!(out, "\x1b[37m~\x1b[K").unwrap();
                }
            } else {
                let file_row = y + buf.rowoff;
                if file_row < buf.rows.len() {
                    let line = &buf.rows[file_row];
                    if line.is_empty() {
                        write!(out, "\x1b[39;0m\x1b[K").unwrap();
                    } else {
                        // TODO syntax highlight
                        // Simple rendering ignoring search for now
                        // For search highlighting, we need to check if this row contains matches
                        let mut rendered = String::new();
                        // We'll need to handle coloff and highlighting
                        // For simplicity, just render without highlight if not searching
                        if editor.searching && !editor.search_query.is_empty() {
