    rowoff: usize,
    coloff: usize,
}

impl Buffer {
    fn new(filename: Option<String>, rows: Vec<String>) -> Self {
        Self { filename, rows, dirty:false, cx:0, cy:0, rowoff:0, coloff:0 }
    }
}

struct Editor {
    buffers: Vec<Buffer>,
    cur_buf: usize,
    screen_rows: usize,
    screen_cols: usize,
