fn read_file_rows(path: &str) -> io::Result<Vec<String>> {
    let data = fs::read(path)?;
    if data.is_empty() { return Ok(vec![]); }
    let text = match String::from_utf8(data) {
        Ok(s) => s,
        Err(_) => { return Err(io::Error::new(io::ErrorKind::InvalidData, "stream did not contain valid UTF-8")); }
    };
    let mut lines: Vec<String> = text.split('\n').map(|s| s.to_string()).collect();
    if text.ends_with('\n') { if !lines.is_empty() { lines.pop(); } }
    Ok(lines)
}

#[derive(Clone, Debug)]
struct Snapshot {
    rows: Vec<String>,
    cx: usize,
    cy: usize,
}

#[derive(Clone, Debug)]
struct Buffer {
    filename: Option<String>,
    rows: Vec<String>,
    dirty: bool,
    cx: usize,
    cy: usize,
    rowoff: usize,
    coloff: usize,
    undo_stack: Vec<Snapshot>,
    redo_stack: Vec<Snapshot>,
    // For grouping, track last edit type?
    last_edit_was_insert: bool,
}

impl Buffer {
    fn new(filename: Option<String>, rows: Vec<String>) -> Self {
        Self { filename, rows, dirty:false, cx:0, cy:0, rowoff:0, coloff:0, undo_stack: Vec::new(), redo_stack: Vec::new(), last_edit_was_insert: false }
    }
    fn push_snapshot(&mut self) {
        let snap = Snapshot { rows: self.rows.clone(), cx: self.cx, cy: self.cy };
        self.undo_stack.push(snap);
        self.redo_stack.clear();
    }
    fn push_snapshot_for_insert(&mut self) {
        // Group consecutive inserts: only push if last edit was not insert
        if !self.last_edit_was_insert {
            self.push_snapshot();
        }
        self.last_edit_was_insert = true;
    }
    fn push_snapshot_for_delete(&mut self) {
        if self.last_edit_was_insert {
            // If switching from insert to delete, push?
            self.push_snapshot();
        } else {
            // For delete, we push each time? To match observed where backspace was separate from insert, we should push before delete if last was insert or if undo stack empty?
            // Actually we want delete to be separate group from insert.
            // So if last was insert, push new snapshot for delete grouping start?
            // But we already pushed for insert before, so delete should push new?
            // Let's push if last was insert
            self.push_snapshot();
        }
        self.last_edit_was_insert = false;
    }
    fn push_snapshot_for_newline(&mut self) {
        self.push_snapshot();
        self.last_edit_was_insert = false;
    }
}

fn enable_raw_mode() -> io::Result<Termios> {
    unsafe {
        let mut orig = std::mem::zeroed::<Termios>();
        if tcgetattr(STDIN_FD, &mut orig) != 0 { return Err(io::Error::last_os_error()); }
        let mut raw = orig;
        raw.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        raw.c_oflag &= !(OPOST);
        raw.c_cflag |= CS8;
        raw.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        raw.c_cc[VMIN]=0;
        raw.c_cc[VTIME]=1;
        if tcsetattr(STDIN_FD, TCSANOW, &raw)!=0 { return Err(io::Error::last_os_error()); }
        Ok(orig)
    }
}
fn disable_raw_mode(orig: &Termios) { unsafe { let _ = tcsetattr(STDIN_FD, TCSANOW, orig); } }

#[derive(Debug, PartialEq, Clone)]
enum Key {
    Ctrl(u8),
    Char(char),
    Alt(char),
    ArrowUp,
    ArrowDown,
    ArrowLeft,
    ArrowRight,
    Home,
    End,
    PageUp,
    PageDown,
    Delete,
    Backspace,
    Esc,
    Unknown,
}

fn parse_csi(s: &str) -> Key {
    match s {
        "\x1b[A" => Key::ArrowUp,
        "\x1b[B" => Key::ArrowDown,
        "\x1b[C" => Key::ArrowRight,
        "\x1b[D" => Key::ArrowLeft,
        "\x1b[H" => Key::Home,
        "\x1b[F" => Key::End,
        "\x1b[1~" => Key::Home,
        "\x1b[4~" => Key::End,
        "\x1b[3~" => Key::Delete,
        "\x1b[5~" => Key::PageUp,
        "\x1b[6~" => Key::PageDown,
        "\x1b[1;5A" => Key::Ctrl(16), // Ctrl-UP
        "\x1b[1;5B" => Key::Ctrl(14), // Ctrl-DOWN
        "\x1b[1;5C" => Key::Alt('f'), // Ctrl-RIGHT
        "\x1b[1;5D" => Key::Alt('b'), // Ctrl-LEFT
        "\x1b[1;3C" => Key::Ctrl(5), // Alt-RIGHT
        "\x1b[1;3D" => Key::Ctrl(1), // Alt-LEFT
        _ => Key::Unknown,
    }
}

fn read_input() -> io::Result<Option<Key>> {
    let mut buf = [0u8; 1];
    unsafe {
        let n = read(STDIN_FD, buf.as_mut_ptr(), 1);
        if n <=0 { return Ok(None); }
        let b = buf[0];
        if b == 27 {
            let mut seq = vec![b];
            for _ in 0..6 {
                let mut extra = [0u8; 32];
                let n2 = read(STDIN_FD, extra.as_mut_ptr(), extra.len());
                if n2>0 {
                    seq.extend_from_slice(&extra[..n2 as usize]);
                    if seq.len()>=2 {
                        if seq[1]==b'[' || seq[1]==b'O' {
                            let last = seq[seq.len()-1];
                            if (b'A'..=b'Z').contains(&last) || (b'a'..=b'z').contains(&last) || last==b'~' { break; }
                            continue;
                        } else { break; }
                    } else { break; }
                } else { break; }
            }
            if seq.len()==1 {
                return Ok(Some(Key::Ctrl(27)));
            } else if seq.len()==2 {
                let ch = seq[1] as char;
                return Ok(Some(Key::Alt(ch)));
            } else {
                let s = String::from_utf8_lossy(&seq);
                let k = parse_csi(&s);
                if k != Key::Unknown {
                    return Ok(Some(k));
                }
                return Ok(Some(Key::Unknown));
            }
        }
        if b == 127 { return Ok(Some(Key::Backspace)); }
        if b < 32 {
            return Ok(Some(Key::Ctrl(b)));
        }
        if b < 0x80 {
            return Ok(Some(Key::Char(b as char)));
        }
        let mut utf8_bytes = vec![b];
        let mut needed = 0;
        if b & 0b11100000 == 0b11000000 { needed=1; }
        else if b & 0b11110000 == 0b11100000 { needed=2; }
        else if b & 0b11111000 == 0b11110000 { needed=3; }
        else { return Ok(Some(Key::Unknown)); }
        for _ in 0..needed {
            let mut extra = [0u8;1];
            let n2 = read(STDIN_FD, extra.as_mut_ptr(),1);
            if n2>0 { utf8_bytes.push(extra[0]); } else { break; }
        }
        let s = String::from_utf8_lossy(&utf8_bytes);
        if let Some(ch) = s.chars().next() {
            return Ok(Some(Key::Char(ch)));
        }
        return Ok(Some(Key::Unknown));
    }
}

