                    let cy = editor.buffers[cur].cy;
                    let row = &mut editor.buffers[cur].rows[cy];
                    let mut chars: Vec<char> = row.chars().collect();
                    chars.insert(cx, ch);
                    *row = chars.into_iter().collect();
                    editor.buffers[cur].cx+=1;
                    editor.buffers[cur].dirty=true;
