                let cy = editor.buffers[cur].cy;
                let current_row = editor.buffers[cur].rows.get(cy).cloned().unwrap_or_else(|| String::new());
                let chars: Vec<char> = current_row.chars().collect();
                let left: String = chars[..cx].iter().collect();
                let right: String = chars[cx..].iter().collect();
                editor.buffers[cur].rows[cy]=left;
                editor.buffers[cur].rows.insert(cy+1, right);
                editor.buffers[cur].cy+=1;
