fn enable_raw_mode() -> io::Result<Termios> {
    unsafe {
        let mut orig = std::mem::zeroed::<Termios>();
        if tcgetattr(STDIN_FD, &mut orig) != 0 { return Err(io::Error::last_os_error()); }
        let mut raw = orig;
        raw.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        raw.c_oflag &= !(OPOST);
        raw.c_cflag |= CS8;
        raw.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        raw.c_cc[VMIN]=0;
        raw.c_cc[VTIME]=1;
        if tcsetattr(STDIN_FD, TCSANOW, &raw)!=0 { return Err(io::Error::last_os_error()); }
        Ok(orig)
    }
}
fn disable_raw_mode(orig: &Termios) { unsafe { let _ = tcsetattr(STDIN_FD, TCSANOW, orig); } }

