fn highlight_keywords(line: &str, keywords: &[&str], color: &str) -> String {
    // This is a very naive implementation that replaces keywords with colored versions if surrounded by non-word chars
    // We'll implement scanning
    let mut result = String::new();
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        // Try to match any keyword at position i
        let mut matched = None;
        let mut matched_len = 0;
        for &kw in keywords {
            let kw_chars: Vec<char> = kw.chars().collect();
            if i + kw_chars.len() <= chars.len() {
                let slice: String = chars[i..i+kw_chars.len()].iter().collect();
                if slice == kw {
                    // Check word boundaries
                    let prev_ok = if i==0 { true } else { !is_word_char(chars[i-1]) };
                    let next_ok = if i+kw_chars.len() >= chars.len() { true } else { !is_word_char(chars[i+kw_chars.len()]) };
                    if prev_ok && next_ok {
                        if kw_chars.len() > matched_len {
                            matched = Some(kw);
                            matched_len = kw_chars.len();
                        }
                    }
                }
            }
        }
        if let Some(kw) = matched {
            result.push_str(&format!("\x1b[{}m{}\x1b[39;0m", color, kw));
            i += matched_len;
        } else {
            result.push(chars[i]);
            i+=1;
        }
    }
    result
}

