                    let cy = editor.buffers[cur].cy;
                    let current_row = editor.buffers[cur].rows.get(cy).cloned().unwrap_or_else(|| String::new());
                    let chars: Vec<char> = current_row.chars().collect();
                    let left: String = chars[..cx].iter().collect();
                    let right: String = chars[cx..].iter().collect();
                    if editor.buffers[cur].rows.is_empty() { editor.buffers[cur].rows.push(left); }
                    else { editor.buffers[cur].rows[cy]=left; }
                    editor.buffers[cur].rows.insert(cy+1, right);
                    editor.buffers[cur].cy+=1;
                    editor.buffers[cur].cx=0;
                    editor.buffers[cur].dirty=true;
                    draw_screen(&mut editor);
                } else {
                    let cur=editor.cur_buf;
                    if editor.buffers[cur].rows.is_empty() { editor.buffers[cur].rows.push(String::new()); }
                    editor.buffers[cur].push_snapshot_for_insert();
                    let cx = editor.buffers[cur].cx;
                    let cy = editor.buffers[cur].cy;
                    let row = &mut editor.buffers[cur].rows[cy];
                    let mut chars: Vec<char> = row.chars().collect();
                    chars.insert(cx, ch);
                    *row = chars.into_iter().collect();
                    editor.buffers[cur].cx+=1;
                    editor.buffers[cur].dirty=true;
                    draw_screen(&mut editor);
                }
            },
            Key::Ctrl(13) => {
                let cur=editor.cur_buf;
                editor.buffers[cur].push_snapshot_for_newline();
                let cx = editor.buffers[cur].cx;
                let cy = editor.buffers[cur].cy;
                let current_row = editor.buffers[cur].rows.get(cy).cloned().unwrap_or_else(|| String::new());
                let chars: Vec<char> = current_row.chars().collect();
                let left: String = chars[..cx].iter().collect();
                let right: String = chars[cx..].iter().collect();
                if editor.buffers[cur].rows.is_empty() { editor.buffers[cur].rows.push(left); }
                else { editor.buffers[cur].rows[cy]=left; }
                editor.buffers[cur].rows.insert(cy+1, right);
                editor.buffers[cur].cy+=1;
                editor.buffers[cur].cx=0;
                editor.buffers[cur].dirty=true;
                draw_screen(&mut editor);
            },
            Key::Backspace | Key::Ctrl(8) => {
                let cur=editor.cur_buf;
                if editor.buffers[cur].cx>0 {
                    editor.buffers[cur].push_snapshot_for_delete();
                    let cx = editor.buffers[cur].cx;
                    let cy = editor.buffers[cur].cy;
                    let row = &mut editor.buffers[cur].rows[cy];
                    let mut chars: Vec<char> = row.chars().collect();
                    chars.remove(cx-1);
                    *row = chars.into_iter().collect();
                    editor.buffers[cur].cx-=1;
                    editor.buffers[cur].dirty=true;
                    draw_screen(&mut editor);
                } else if editor.buffers[cur].cy>0 {
                    editor.buffers[cur].push_snapshot_for_delete();
                    let cy = editor.buffers[cur].cy;
                    let prev_len = editor.buffers[cur].rows[cy-1].chars().count();
                    let current = editor.buffers[cur].rows.remove(cy);
                    editor.buffers[cur].rows[cy-1].push_str(&current);
                    editor.buffers[cur].cy-=1;
                    editor.buffers[cur].cx=prev_len;
                    editor.buffers[cur].dirty=true;
                    draw_screen(&mut editor);
                }
            },
            Key::Delete | Key::Ctrl(4) => {
                let cur=editor.cur_buf;
                let cx = editor.buffers[cur].cx;
                let cy = editor.buffers[cur].cy;
                if cy < editor.buffers[cur].rows.len() {
                    let row_len = editor.buffers[cur].rows[cy].chars().count();
                    if cx < row_len {
                        editor.buffers[cur].push_snapshot_for_delete();
                        let row = &mut editor.buffers[cur].rows[cy];
                        let mut chars: Vec<char> = row.chars().collect();
                        chars.remove(cx);
                        *row = chars.into_iter().collect();
                        editor.buffers[cur].dirty=true;
                        draw_screen(&mut editor);
                    } else if cy+1 < editor.buffers[cur].rows.len() {
                        editor.buffers[cur].push_snapshot_for_delete();
                        let next = editor.buffers[cur].rows.remove(cy+1);
                        editor.buffers[cur].rows[cy].push_str(&next);
                        editor.buffers[cur].dirty=true;
                        draw_screen(&mut editor);
                    }
                }
            },
            Key::Ctrl(23) => {
                let cur=editor.cur_buf;
                let cx = editor.buffers[cur].cx;
