                    editor.buffers[cur].redo_stack.push(redo);
                    editor.buffers[cur].rows = snap.rows;
                    editor.buffers[cur].cx = snap.cx;
                    editor.buffers[cur].cy = snap.cy;
                    editor.buffers[cur].dirty=true;
                    editor.buffers[cur].last_edit_was_insert=false;
                    draw_screen(&mut editor);
                } else {
                    editor.status_msg="No older change".to_string();
                    draw_screen(&mut editor);
                }
            },
            Key::Ctrl(18) => {
                let cur=editor.cur_buf;
                if let Some(snap) = editor.buffers[cur].redo_stack.pop() {
                    let undo = Snapshot { rows: editor.buffers[cur].rows.clone(), cx: editor.buffers[cur].cx, cy: editor.buffers[cur].cy };
                    editor.buffers[cur].undo_stack.push(undo);
                    editor.buffers[cur].rows = snap.rows;
                    editor.buffers[cur].cx = snap.cx;
                    editor.buffers[cur].cy = snap.cy;
                    editor.buffers[cur].dirty=true;
                    editor.buffers[cur].last_edit_was_insert=false;
                    draw_screen(&mut editor);
                } else {
                    editor.status_msg="No newer change".to_string();
                    draw_screen(&mut editor);
                }
