                        editor.buffers[cur].cx = pos.min(chars.len());
                        draw_screen(&mut editor);
                    },
                    'b' => {
                        let cur=editor.cur_buf;
                        if editor.buffers[cur].rows.is_empty() { continue; }
                        let cx = editor.buffers[cur].cx;
                        let line = &editor.buffers[cur].rows[editor.buffers[cur].cy];
                        let chars: Vec<char> = line.chars().collect();
                        if cx>0 {
                            let mut pos=cx-1;
                            while pos>0 && !is_word_char(chars[pos]) { pos-=1; }
                            while pos>0 && is_word_char(chars[pos-1]) { pos-=1; }
                            editor.buffers[cur].cx=pos;
                            draw_screen(&mut editor);
                        }
                    },
                    'n' => {
                        let cur=editor.cur_buf;
                        let rows = editor.buffers[cur].rows.clone();
                        let mut cy = editor.buffers[cur].cy;
                        while cy < rows.len() && !rows[cy].is_empty() { cy+=1; }
                        while cy < rows.len() && rows[cy].is_empty() { cy+=1; }
                        if cy < rows.len() { editor.buffers[cur].cy=cy; editor.buffers[cur].cx=0; }
                        else { editor.buffers[cur].cy = rows.len().saturating_sub(1); }
                        draw_screen(&mut editor);
                    },
                    'p' => {
                        let cur=editor.cur_buf;
                        let rows = editor.buffers[cur].rows.clone();
                        let mut cy = editor.buffers[cur].cy;
                        if cy>0 {
                            cy-=1;
                            while cy>0 && rows[cy].is_empty() { cy-=1; }
                            while cy>0 && !rows[cy-1].is_empty() { cy-=1; }
                            editor.buffers[cur].cy=cy;
                            editor.buffers[cur].cx=0;
                        }
                        draw_screen(&mut editor);
                    },
                    '<' => { let cur=editor.cur_buf; editor.buffers[cur].cy=0; editor.buffers[cur].cx=0; editor.buffers[cur].rowoff=0; draw_screen(&mut editor); },
                    '>' => {
                        let cur=editor.cur_buf;
                        let len = editor.buffers[cur].rows.len();
                        if len>0 { editor.buffers[cur].cy=len-1; editor.buffers[cur].cx=editor.buffers[cur].rows[len-1].chars().count(); }
                        draw_screen(&mut editor);
                    },
                    'x' => {
                        if editor.buffers.len()>1 {
                            if editor.cur_buf==0 { editor.cur_buf = editor.buffers.len()-1; } else { editor.cur_buf-=1; }
                            draw_screen(&mut editor);
                        }
                    },
                    _ => {
                        editor.status_msg=format!("Key 'M-{}' not mapped", ch);
                        let mut out=io::stdout();
                        write!(out, "\x1b[?25l").unwrap();
                        write!(out, "\x1b[{}H\x1b[97m\x1b[41m{}\x1b[39;0m\x1b[K", editor.screen_rows+2, editor.status_msg).unwrap();
                        let buf=&editor.buffers[editor.cur_buf];
                        write!(out, "\x1b[{};{}H", buf.cy - buf.rowoff +1, display_cx(buf)+1).unwrap();
                        write!(out, "\x1b[?25h").unwrap();
                        out.flush().unwrap();
                    }
                }
            },
            _ => {}
        }
    }

    print!("\x1b[?25l\x1b[?1049l\x1b[H"); let _=io::stdout().flush();
    disable_raw_mode(&orig_termios);
}
