    println!("    Ctrl-W                        : Delete a word");
    println!("    Ctrl-J                        : Delete until head of line");
    println!("    Ctrl-K                        : Delete until end of line");
    println!("    Ctrl-U                        : Undo last change");
    println!("    Ctrl-R                        : Redo last undo change");
    println!("    Ctrl-G                        : Search text");
    println!("    Ctrl-M                        : New line");
    println!("    Ctrl-L                        : Refresh screen");
    println!("    Ctrl-?                        : Show this help");
    println!();
    println!("Options:");
    println!("    -v, --version       Print version");
    println!("    -h, --help          Print this help");
    println!();
}

fn read_file_rows(path: &str) -> io::Result<Vec<String>> {
    let data = fs::read(path)?;
    if data.is_empty() { return Ok(vec![]); }
    let text = match String::from_utf8(data) {
        Ok(s) => s,
        Err(_) => { return Err(io::Error::new(io::ErrorKind::InvalidData, "stream did not contain valid UTF-8")); }
    };
    let mut lines: Vec<String> = text.split('\n').map(|s| s.to_string()).collect();
    if text.ends_with('\n') { if !lines.is_empty() { lines.pop(); } }
    Ok(lines)
}

#[derive(Clone, Debug)]
struct Snapshot { rows: Vec<String>, cx: usize, cy: usize, }

#[derive(Clone, Debug)]
struct Buffer {
    filename: Option<String>,
    rows: Vec<String>,
    dirty: bool,
    cx: usize,
    cy: usize,
    rowoff: usize,
    coloff: usize,
    undo_stack: Vec<Snapshot>,
    redo_stack: Vec<Snapshot>,
    last_edit_was_insert: bool,
}

impl Buffer {
    fn new(filename: Option<String>, rows: Vec<String>) -> Self {
        Self { filename, rows, dirty:false, cx:0, cy:0, rowoff:0, coloff:0, undo_stack: Vec::new(), redo_stack: Vec::new(), last_edit_was_insert: false }
    }
    fn push_snapshot(&mut self) {
        let snap = Snapshot { rows: self.rows.clone(), cx: self.cx, cy: self.cy };
        self.undo_stack.push(snap);
        self.redo_stack.clear();
    }
    fn push_snapshot_for_insert(&mut self) {
        if !self.last_edit_was_insert { self.push_snapshot(); }
        self.last_edit_was_insert = true;
    }
    fn push_snapshot_for_delete(&mut self) {
        if self.last_edit_was_insert { self.push_snapshot(); }
        else { self.push_snapshot(); }
        self.last_edit_was_insert = false;
    }
    fn push_snapshot_for_newline(&mut self) {
        self.push_snapshot();
        self.last_edit_was_insert = false;
    }
}

fn enable_raw_mode() -> io::Result<Termios> {
    unsafe {
        let mut orig = std::mem::zeroed::<Termios>();
        if tcgetattr(STDIN_FD, &mut orig) != 0 { return Err(io::Error::last_os_error()); }
        let mut raw = orig;
        raw.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        raw.c_oflag &= !(OPOST);
        raw.c_cflag |= CS8;
        raw.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        raw.c_cc[VMIN]=0;
        raw.c_cc[VTIME]=1;
        if tcsetattr(STDIN_FD, TCSANOW, &raw)!=0 { return Err(io::Error::last_os_error()); }
        Ok(orig)
    }
}
fn disable_raw_mode(orig: &Termios) { unsafe { let _ = tcsetattr(STDIN_FD, TCSANOW, orig); } }

#[derive(Debug, PartialEq, Clone)]
enum Key {
    Ctrl(u8),
    Char(char),
    Alt(char),
    ArrowUp, ArrowDown, ArrowLeft, ArrowRight,
    Home, End, PageUp, PageDown, Delete, Backspace, Esc, Unknown,
}

fn parse_csi(s: &str) -> Key {
    match s {
        "\x1b[A" => Key::ArrowUp,
        "\x1b[B" => Key::ArrowDown,
        "\x1b[C" => Key::ArrowRight,
        "\x1b[D" => Key::ArrowLeft,
        "\x1b[H" => Key::Home,
        "\x1b[F" => Key::End,
        "\x1b[1~" => Key::Home,
        "\x1b[4~" => Key::End,
        "\x1b[3~" => Key::Delete,
        "\x1b[5~" => Key::PageUp,
        "\x1b[6~" => Key::PageDown,
        "\x1b[1;5A" => Key::Ctrl(16),
        "\x1b[1;5B" => Key::Ctrl(14),
        "\x1b[1;5C" => Key::Alt('f'),
        "\x1b[1;5D" => Key::Alt('b'),
        "\x1b[1;3C" => Key::Ctrl(5),
        "\x1b[1;3D" => Key::Ctrl(1),
        _ => Key::Unknown,
    }
}

fn read_input() -> io::Result<Option<Key>> {
    let mut buf = [0u8; 1];
    unsafe {
        let n = read(STDIN_FD, buf.as_mut_ptr(), 1);
        if n <=0 { return Ok(None); }
        let b = buf[0];
        if b == 27 {
            let mut seq = vec![b];
            for _ in 0..6 {
                let mut extra = [0u8; 32];
                let n2 = read(STDIN_FD, extra.as_mut_ptr(), extra.len());
                if n2>0 {
                    seq.extend_from_slice(&extra[..n2 as usize]);
                    if seq.len()>=2 {
                        if seq[1]==b'[' || seq[1]==b'O' {
                            let last = seq[seq.len()-1];
                            if (b'A'..=b'Z').contains(&last) || (b'a'..=b'z').contains(&last) || last==b'~' { break; }
                            continue;
                        } else { break; }
                    } else { break; }
                } else { break; }
            }
            if seq.len()==1 { return Ok(Some(Key::Ctrl(27))); }
            else if seq.len()==2 { return Ok(Some(Key::Alt(seq[1] as char))); }
            else {
                let s = String::from_utf8_lossy(&seq);
                let k = parse_csi(&s);
                if k != Key::Unknown { return Ok(Some(k)); }
                return Ok(Some(Key::Unknown));
            }
        }
        if b == 127 { return Ok(Some(Key::Backspace)); }
        if b < 32 { return Ok(Some(Key::Ctrl(b))); }
        if b < 0x80 { return Ok(Some(Key::Char(b as char))); }
        let mut utf8_bytes = vec![b];
        let mut needed = 0;
        if b & 0b11100000 == 0b11000000 { needed=1; }
        else if b & 0b11110000 == 0b11100000 { needed=2; }
        else if b & 0b11111000 == 0b11110000 { needed=3; }
        else { return Ok(Some(Key::Unknown)); }
        for _ in 0..needed {
            let mut extra = [0u8;1];
            let n2 = read(STDIN_FD, extra.as_mut_ptr(),1);
            if n2>0 { utf8_bytes.push(extra[0]); } else { break; }
        }
        let s = String::from_utf8_lossy(&utf8_bytes);
        if let Some(ch) = s.chars().next() { return Ok(Some(Key::Char(ch))); }
        return Ok(Some(Key::Unknown));
    }
}

struct Editor {
    buffers: Vec<Buffer>,
    cur_buf: usize,
    screen_rows: usize,
    screen_cols: usize,
    help: bool,
    quit_times: usize,
    status_msg: String,
    prompt: Option<Prompt>,
    search_query: String,
    search_matches: Vec<(usize, usize)>,
    search_idx: usize,
    searching: bool,
}

#[derive(Debug, Clone)]
enum Prompt { Save(String, usize), Open(String, usize), Search(String, usize), }

fn should_show_welcome(editor: &Editor) -> bool {
    if editor.help { return false; }
    if editor.prompt.is_some() { return false; }
    if editor.searching { return false; }
    if editor.buffers.len()!=1 { return false; }
    let buf = &editor.buffers[editor.cur_buf];
    if buf.filename.is_some() { return false; }
    if buf.rows.len()==1 && buf.rows[0].is_empty() { return true; }
    if buf.rows.is_empty() { return true; }
    false
}

fn filetype_for_buffer(buf: &Buffer) -> &'static str {
    if let Some(fname) = &buf.filename {
        if let Some(dot) = fname.rfind('.') {
            let ext = &fname[dot+1..];
            match ext {
                "c" | "h" => return "c",
                "cpp" | "hpp" | "cc" => return "c++",
                "rs" => return "rust",
                "py" => return "python",
                "js" => return "javascript",
                "go" => return "go",
                _ => {}
            }
        }
    }
    "plain"
}

fn is_word_char(c: char) -> bool { c.is_alphanumeric() || c == '_' }

fn highlight_line(filetype: &str, line: &str) -> String {
    // Use full highlighter
    let (kw_blue, kw_red, kw_yellow, kw_cyan, kw_magenta) : (Vec<&str>, Vec<&str>, Vec<&str>, Vec<&str>, Vec<&str>) = match filetype {
        "rust" => (
            vec!["as","const","crate","dyn","enum","extern","fn","impl","let","mod","move","mut","pub","ref","Self","static","struct","super","trait","type","unsafe","use","where","async","await"],
            vec!["break","continue","else","for","if","in","loop","match","return","while"],
            vec!["bool","char","i32","u32","i64","u64","String","usize","isize","f32","f64","Box","Option","Result","Vec"],
            vec!["self"],
            vec!["true","false"],
        ),
        "c" => (
            vec!["auto","const","enum","extern","register","restrict","static","struct","typedef","union","volatile","inline"],
            vec!["break","case","continue","default","do","else","for","goto","if","return","switch","while"],
            vec!["char","double","float","int","long","short","signed","unsigned","void"],
            vec![],
            vec!["true","false","NULL"],
        ),
        "c++" => (
            vec!["auto","const","enum","extern","register","restrict","static","struct","typedef","union","volatile","inline","bool","class","const_cast","delete","dynamic_cast","explicit","export","friend","mutable","namespace","new","operator","private","protected","public","reinterpret_cast","static_cast","template","typeid","typename","using","virtual"],
            vec!["break","case","continue","default","do","else","for","goto","if","return","switch","while","catch","throw","try"],
            vec!["char","double","float","int","long","short","signed","unsigned","void","wchar_t"],
            vec!["this"],
            vec!["true","false","NULL","nullptr"],
        ),
        "go" => (
            vec!["defer","func","go","interface","map","package","range","struct","chan","const","type","var","import"],
            vec!["break","case","continue","default","else","fallthrough","for","goto","if","return","select","switch"],
            vec!["int","bool","string","byte","float64","int8","int16","int32","int64","uint","uint8","uint16","uint32","uint64","uintptr","float32","float64","complex64","complex128","rune","error"],
            vec![],
            vec!["true","false","nil"],
        ),
        "python" => (
            vec!["and","as","assert","class","def","del","from","global","import","in","is","lambda","nonlocal","not","or","with"],
            vec!["break","continue","elif","else","except","finally","for","if","pass","raise","return","try","while","yield"],
            vec!["range","str","int","float","list","dict","set","tuple"],
            vec!["None","self"],
            vec!["False","True"],
        ),
        "javascript" => (
            vec!["debugger","delete","function","in","instanceof","new","typeof","var","void","with","let","const","class","extends","import","export"],
            vec!["break","case","catch","continue","default","do","else","finally","for","if","return","switch","throw","try","while"],
            vec!["Math","Date","String","Number","Boolean","Object","Array","RegExp","Error","Promise","JSON"],
            vec!["this","null","undefined"],
            vec!["true","false"],
        ),
        _ => (vec![], vec![], vec![], vec![], vec![]),
    };
    let decl_keywords: Vec<&str> = match filetype {
        "rust" => vec!["fn","let","mod","struct","enum","trait","type","const","static"],
        "go" => vec!["func","var","package","type","const"],
        "python" => vec!["def","class"],
        "javascript" => vec!["function","var","let","const","class"],
        _ => vec![],
    };

    let mut result = String::new();
    let chars: Vec<char> = line.chars().collect();
    let mut i=0;
    let mut expect_func = false;
    let mut expect_func_after_mut = false;

    while i < chars.len() {
        let c = chars[i];
        // comments
        if filetype=="c" || filetype=="c++" || filetype=="rust" || filetype=="javascript" || filetype=="go" {
            if i+1 < chars.len() && chars[i]=='/' && chars[i+1]=='/' {
                let comment: String = chars[i..].iter().collect();
                result.push_str(&format!("\x1b[90m{}\x1b[39;0m", comment));
                break;
            }
            if i+1 < chars.len() && chars[i]=='/' && chars[i+1]=='*' {
                let mut j=i+2;
                while j+1 < chars.len() {
                    if chars[j]=='*' && chars[j+1]=='/' {
                        let comment: String = chars[i..j+2].iter().collect();
                        result.push_str(&format!("\x1b[90m{}\x1b[39;0m", comment));
                        i=j+2;
                        break;
                    }
                    j+=1;
                }
                if j+1 >= chars.len() {
                    let comment: String = chars[i..].iter().collect();
                    result.push_str(&format!("\x1b[90m{}\x1b[39;0m", comment));
                    break;
                }
                continue;
            }
        } else if filetype=="python" {
            if c=='#' {
                let comment: String = chars[i..].iter().collect();
                result.push_str(&format!("\x1b[90m{}\x1b[39;0m", comment));
                break;
            }
            if i+2 < chars.len() {
                let three: String = chars[i..i+3].iter().collect();
                if three=="\"\"\"" || three=="'''" {
                    let mut j=i+3;
                    while j+2 < chars.len() {
                        let t: String = chars[j..j+3].iter().collect();
                        if t==three {
                            let s: String = chars[i..j+3].iter().collect();
                            result.push_str(&format!("\x1b[32m{}\x1b[39;0m", s));
                            i=j+3;
                            break;
                        }
                        j+=1;
                    }
                    if j+2 >= chars.len() {
                        let s: String = chars[i..].iter().collect();
                        result.push_str(&format!("\x1b[32m{}\x1b[39;0m", s));
                        break;
                    }
                    continue;
                }
            }
        }

        // strings
        if c=='"' || c=='\'' {
            let quote=c;
            let mut j=i+1;
            let mut esc=false;
            while j < chars.len() {
                if esc { esc=false; j+=1; continue; }
                if chars[j]=='\\' { esc=true; j+=1; continue; }
                if chars[j]==quote { break; }
                j+=1;
            }
            if j < chars.len() {
                let s: String = chars[i..j+1].iter().collect();
                if (filetype=="c" || filetype=="c++" || filetype=="rust" || filetype=="go" || filetype=="javascript") && quote=='\'' {
                    let inside: String = chars[i+1..j].iter().collect();
                    if inside.chars().count()>1 && !(inside.starts_with('\\') && inside.chars().count()<=2) {
                        result.push_str(&s);
                        i=j+1;
                        expect_func=false;
                        continue;
                    }
                }
                result.push_str(&format!("\x1b[32m{}\x1b[39;0m", s));
                i=j+1;
                expect_func=false;
                expect_func_after_mut=false;
                continue;
            } else {
                let s: String = chars[i..].iter().collect();
                result.push_str(&format!("\x1b[32m{}\x1b[39;0m", s));
                break;
            }
        }

        // numbers
        if c.is_ascii_digit() {
            let prev_ok = if i==0 { true } else { !is_word_char(chars[i-1]) };
            if prev_ok {
                let mut j=i;
                while j < chars.len() {
                    let ch = chars[j];
                    if ch.is_ascii_hexdigit() || ch=='x' || ch=='X' || ch=='b' || ch=='B' || ch=='.' || ch=='_' { j+=1; } else { break; }
                }
                let num: String = chars[i..j].iter().collect();
                result.push_str(&format!("\x1b[95m{}\x1b[39;0m", num));
                i=j;
                expect_func=false;
                expect_func_after_mut=false;
                continue;
            }
        }

        if is_word_char(c) {
            let mut j=i;
            while j < chars.len() && is_word_char(chars[j]) { j+=1; }
            let word: String = chars[i..j].iter().collect();
            let is_decl = decl_keywords.contains(&word.as_str());
            let is_mut = word=="mut";
            if kw_blue.contains(&word.as_str()) {
                result.push_str(&format!("\x1b[94m{}\x1b[39;0m", word));
                if is_decl { expect_func=true; expect_func_after_mut=false; }
                else if is_mut && expect_func { expect_func_after_mut=true; }
                else { if !(is_mut && (expect_func || expect_func_after_mut)) { expect_func=false; } }
            } else if kw_red.contains(&word.as_str()) {
                result.push_str(&format!("\x1b[91m{}\x1b[39;0m", word));
                expect_func=false;
                expect_func_after_mut=false;
            } else if kw_yellow.contains(&word.as_str()) {
                result.push_str(&format!("\x1b[33m{}\x1b[39;0m", word));
            } else if kw_cyan.contains(&word.as_str()) {
                result.push_str(&format!("\x1b[96m{}\x1b[39;0m", word));
                expect_func=false;
                expect_func_after_mut=false;
            } else if kw_magenta.contains(&word.as_str()) {
                result.push_str(&format!("\x1b[95m{}\x1b[39;0m", word));
                expect_func=false;
                expect_func_after_mut=false;
            } else {
                if expect_func || expect_func_after_mut {
                    result.push_str(&format!("\x1b[93m{}\x1b[39;0m", word));
                } else {
                    result.push_str(&word);
                }
                expect_func_after_mut=false;
            }
            i=j;
            continue;
        }

        if c=='=' || c=='(' || c==')' || c=='{' || c=='}' || c==';' || c==':' || c==',' {
            expect_func=false;
            expect_func_after_mut=false;
        }

        result.push(c);
        i+=1;
    }
    result
}

fn truncate_visible(s: &str, coloff: usize, max_cols: usize) -> String {
    let mut result = String::new();
    let mut visible_col = 0;
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\x1b' {
            let mut ansi = String::new();
            ansi.push(c);
            i+=1;
            while i < chars.len() {
                let cc = chars[i];
                ansi.push(cc);
                if (cc >= 'A' && cc <= 'Z') || (cc >= 'a' && cc <= 'z') { break; }
                i+=1;
            }
            result.push_str(&ansi);
            i+=1;
            continue;
        }
        let w = if c=='\t' { 8 - (visible_col % 8) } else if (c as u32)>0x7F { 2 } else { 1 };
        if visible_col < coloff {
            if visible_col + w <= coloff {
                visible_col+=w;
                i+=1;
                continue;
            } else {
                visible_col+=w;
                i+=1;
                continue;
            }
        }
        if visible_col - coloff + w > max_cols { break; }
        result.push(c);
        visible_col+=w;
        i+=1;
    }
    result
}

fn display_cx(buf: &Buffer) -> usize {
    if buf.cy >= buf.rows.len() { return 0; }
    let line = &buf.rows[buf.cy];
    let chars: Vec<char> = line.chars().collect();
    let mut col=0;
    for i in 0..buf.cx.min(chars.len()) {
        let c = chars[i];
        if c=='\t' { col+=8 - (col%8); }
        else if (c as u32)>0x7F { col+=2; }
        else { col+=1; }
    }
    col - buf.coloff
}

fn draw_screen(editor: &mut Editor) {
    let mut out = io::stdout();
    write!(out, "\x1b[?25l").unwrap();
    write!(out, "\x1b[39;0m").unwrap();
    let screen_rows = editor.screen_rows;
    let screen_cols = editor.screen_cols;

    if editor.help {
        let help_keys = vec![
            ("Ctrl-Q","Quit"),
            ("Ctrl-S","Save to file"),
            ("Ctrl-O","Open text buffer"),
            ("Ctrl-X","Next text buffer"),
            ("Alt-X","Previous text buffer"),
            ("Ctrl-P or UP","Move cursor up"),
            ("Ctrl-N or DOWN","Move cursor down"),
            ("Ctrl-F or RIGHT","Move cursor right"),
            ("Ctrl-B or LEFT","Move cursor left"),
            ("Ctrl-A or Alt-LEFT or HOME","Move cursor to head of line"),
            ("Ctrl-E or Alt-RIGHT or END","Move cursor to end of line"),
            ("Ctrl-[ or Ctrl-V or PAGE DOWN","Next page"),
            ("Ctrl-] or Alt-V or PAGE UP","Previous page"),
            ("Alt-F or Ctrl-RIGHT","Move cursor to next word"),
            ("Alt-B or Ctrl-LEFT","Move cursor to previous word"),
            ("Alt-N or Ctrl-DOWN","Move cursor to next paragraph"),
            ("Alt-P or Ctrl-UP","Move cursor to previous paragraph"),
            ("Alt-<","Move cursor to top of file"),
            ("Alt->","Move cursor to bottom of file"),
            ("Ctrl-H or BACKSPACE","Delete character"),
            ("Ctrl-D or DELETE","Delete next character"),
            ("Ctrl-W","Delete a word"),
            ("Ctrl-J","Delete until head of line"),
            ("Ctrl-K","Delete until end of line"),
            ("Ctrl-U","Undo last change"),
            ("Ctrl-R","Redo last undo change"),
            ("Ctrl-G","Search text"),
            ("Ctrl-M","New line"),
            ("Ctrl-L","Refresh screen"),
            ("Ctrl-?","Show this help"),
        ];
        let total_help = help_keys.len();
        if screen_rows >= total_help {
            let start = (screen_rows - total_help)/2;
            for y in 0..screen_rows { write!(out, "\x1b[{}H\x1b[K", y+1).unwrap(); }
            for (i,(k,d)) in help_keys.iter().enumerate() {
                let y = start + i;
                write!(out, "\x1b[{}H       \x1b[96m{:<30}\x1b[39;0m: {}\x1b[K", y+1, k, d).unwrap();
            }
        } else {
            for y in 0..screen_rows {
                write!(out, "\x1b[{}H", y+1).unwrap();
                write!(out, "\x1b[39;0m").unwrap();
                if y < total_help {
                    let (k,d) = &help_keys[y];
                    write!(out, "       \x1b[96m{:<30}\x1b[39;0m: {}\x1b[K", k, d).unwrap();
                } else { write!(out, "\x1b[K").unwrap(); }
            }
        }
    } else {
        let buf = &editor.buffers[editor.cur_buf];
        let welcome = should_show_welcome(editor);
        for y in 0..screen_rows {
            write!(out, "\x1b[{}H", y+1).unwrap();
            if welcome {
                if y == screen_rows/3 {
                    let msg = format!("Kiro editor -- version {}", VERSION);
                    let padding = (screen_cols - msg.len())/2;
                    let spaces = if padding>0 { padding-1 } else {0};
                    write!(out, "\x1b[37m~\x1b[39;0m{}{}\x1b[K", " ".repeat(spaces), msg).unwrap();
                } else { write!(out, "\x1b[37m~\x1b[K").unwrap(); }
            } else {
                let file_row = y + buf.rowoff;
                if file_row < buf.rows.len() {
                    let line = &buf.rows[file_row];
                    if line.is_empty() {
                        write!(out, "\x1b[39;0m\x1b[K").unwrap();
                    } else {
                        let ftype = filetype_for_buffer(buf);
                        let highlighted = if ftype=="plain" { line.clone() } else { highlight_line(&ftype, line) };
                        let truncated = truncate_visible(&highlighted, buf.coloff, screen_cols);
                        write!(out, "{}\x1b[39;0m\x1b[K", truncated).unwrap();
                    }
                } else {
                    write!(out, "\x1b[37m~\x1b[39;0m\x1b[K").unwrap();
                }
            }
        }
    }

    let buf = &editor.buffers[editor.cur_buf];
    let total_buffers = editor.buffers.len();
    let cur_buf_num = editor.cur_buf+1;
    let filename = match &buf.filename { Some(f)=> f.clone(), None=> "[No Name]".to_string() };
    let left_base = format!("\"{}\" - {}/{}", filename, cur_buf_num, total_buffers);
    let left = if buf.dirty { format!("{} (modified)", left_base) } else { left_base };
    let total_rows = buf.rows.len();
    let cur_row = buf.cy+1;
    let ftype = filetype_for_buffer(buf);
    let right = format!("{} {}/{}", ftype, cur_row, total_rows);
    let spaces = if screen_cols > left.len()+right.len() { screen_cols - left.len() - right.len() } else {0};
    write!(out, "\x1b[{}H\x1b[7m{}{}{}\x1b[39;0m", screen_rows+1, left, " ".repeat(spaces), right).unwrap();

    if let Some(prompt) = &editor.prompt {
        match prompt {
            Prompt::Save(input, cx) => {
                let msg = format!("Save as: {} (^G or ESC to cancel)", input);
                let truncated = if msg.len() > screen_cols { msg[..screen_cols].to_string() } else { msg };
                write!(out, "\x1b[{}H{}\x1b[K", screen_rows+2, truncated).unwrap();
                write!(out, "\x1b[{};{}H", screen_rows+2, "Save as: ".len()+cx+1).unwrap();
            },
            Prompt::Open(input, cx) => {
                let msg = format!("Open: {} (Empty name for new text buffer, ^G or ESC to cancel)", input);
                let truncated = if msg.len() > screen_cols { msg[..screen_cols].to_string() } else { msg };
                write!(out, "\x1b[{}H{}\x1b[K", screen_rows+2, truncated).unwrap();
                write!(out, "\x1b[{};{}H", screen_rows+2, "Open: ".len()+cx+1).unwrap();
            },
            Prompt::Search(input, cx) => {
                let msg = format!("Search: {} (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)", input);
                let truncated = if msg.len() > screen_cols { msg[..screen_cols].to_string() } else { msg };
                write!(out, "\x1b[{}H{}\x1b[K", screen_rows+2, truncated).unwrap();
                write!(out, "\x1b[{};{}H", screen_rows+2, "Search: ".len()+cx+1).unwrap();
            }
        }
    } else {
        write!(out, "\x1b[{}H{}\x1b[K", screen_rows+2, editor.status_msg).unwrap();
        let render_cy = buf.cy - buf.rowoff;
        let render_cx = display_cx(buf);
        if render_cy < screen_rows {
            write!(out, "\x1b[{};{}H", render_cy+1, render_cx+1).unwrap();
        }
    }

    write!(out, "\x1b[?25h").unwrap();
    out.flush().unwrap();
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let arg0 = args.get(0).map(|s| s.as_str()).unwrap_or("./executable");
    let mut files: Vec<String> = Vec::new();
    let mut version_flag=false;
    let mut help_flag=false;
    let mut end_of_options=false;
    let mut i=1;
    while i<args.len() {
        let arg=&args[i];
        if end_of_options { files.push(arg.clone()); }
        else if arg=="--" { end_of_options=true; }
        else if arg=="-" { files.push(arg.clone()); }
        else if arg.starts_with("--") {
            if arg=="--version" { version_flag=true; }
            else if arg=="--help" { help_flag=true; }
            else { let name=&arg[2..]; eprintln!("Error: Unrecognized option: '{}'. Please see --help for more details", name); process::exit(1); }
        } else if arg.starts_with('-') && arg.len()>1 {
            for ch in arg[1..].chars() {
                if ch=='v' { version_flag=true; }
                else if ch=='h' { help_flag=true; }
                else { eprintln!("Error: Unrecognized option: '{}'. Please see --help for more details", ch); process::exit(1); }
            }
        } else { files.push(arg.clone()); }
        i+=1;
    }
    if version_flag { println!("{}", VERSION); return; }
    if help_flag { print_help(arg0); return; }

    let ws = match get_winsize() { Ok(ws)=>ws, Err(e)=>{ eprintln!("Error: {}", e); process::exit(1); } };

    for fname in &files {
        let path = std::path::Path::new(fname);
        match fs::metadata(path) {
            Ok(meta) => {
                if meta.is_dir() {
                    let err = io::Error::from_raw_os_error(21);
                    print!("\x1b[?1049h\x1b[?1049l\x1b[H");
                    let _ = io::stdout().flush();
                    eprintln!("Error: {}", err);
                    process::exit(1);
                }
                match fs::File::open(path) {
                    Ok(_)=>{},
                    Err(e)=>{ print!("\x1b[?1049h\x1b[?1049l\x1b[H"); let _=io::stdout().flush(); eprintln!("Error: {}", e); process::exit(1); }
                }
            },
            Err(e)=>{ if e.kind()!=io::ErrorKind::NotFound { print!("\x1b[?1049h\x1b[?1049l\x1b[H"); let _=io::stdout().flush(); eprintln!("Error: {}", e); process::exit(1); } }
        }
    }

    let mut buffers: Vec<Buffer> = Vec::new();
    if files.is_empty() {
        buffers.push(Buffer::new(None, vec![String::new()]));
    } else {
        for fname in files {
            let path = std::path::Path::new(&fname);
            if !path.exists() {
                buffers.push(Buffer::new(Some(fname.clone()), vec![String::new()]));
            } else {
                match read_file_rows(&fname) {
                    Ok(rows)=>{ buffers.push(Buffer::new(Some(fname.clone()), rows)); },
                    Err(e)=>{ print!("\x1b[?1049h\x1b[?1049l\x1b[H"); let _=io::stdout().flush(); eprintln!("Error: {}", e); process::exit(1); }
                }
            }
        }
    }

    let orig_termios = match enable_raw_mode() { Ok(t)=>t, Err(e)=>{ eprintln!("Error: {}", e); process::exit(1); } };
    print!("\x1b[?1049h"); let _=io::stdout().flush();

    let mut editor = Editor {
        buffers,
        cur_buf:0,
        screen_rows: ws.ws_row as usize -2,
        screen_cols: ws.ws_col as usize,
        help:false,
        quit_times:0,
        status_msg: "Ctrl-? for help".to_string(),
        prompt: None,
        search_query: String::new(),
        search_matches: Vec::new(),
        search_idx:0,
        searching:false,
    };

    draw_screen(&mut editor);

    loop {
        let key_opt = match read_input() { Ok(k)=>k, Err(_)=>continue };
        let key = match key_opt { Some(k)=>k, None=>continue };

        match &key {
            Key::Ctrl(17) => {
                if editor.prompt.is_some() { continue; }
                if editor.searching {
                    editor.searching=false;
                    editor.search_query.clear();
                    editor.search_matches.clear();
                    editor.status_msg="Canceled".to_string();
                    editor.prompt=None;
                    draw_screen(&mut editor);
                    continue;
                }
                let any_dirty = editor.buffers.iter().any(|b| b.dirty);
                if any_dirty && editor.quit_times==0 {
                    editor.quit_times+=1;
                    editor.status_msg="At least one file has unsaved changes! Press ^Q again to quit or ^S to save".to_string();
                    let mut out=io::stdout();
                    write!(out, "\x1b[?25l").unwrap();
                    write!(out, "\x1b[{}H\x1b[97m\x1b[41m{}\x1b[39;0m\x1b[K", editor.screen_rows+2, editor.status_msg).unwrap();
                    let buf=&editor.buffers[editor.cur_buf];
                    write!(out, "\x1b[{};{}H", buf.cy - buf.rowoff +1, display_cx(buf)+1).unwrap();
                    write!(out, "\x1b[?25h").unwrap();
                    out.flush().unwrap();
                    continue;
                } else { break; }
            },
            Key::Ctrl(31) => {
                if editor.prompt.is_none() && !editor.searching {
                    editor.help = !editor.help;
                    editor.status_msg = if editor.help { String::new() } else { "Ctrl-? for help".to_string() };
                    draw_screen(&mut editor);
                }
                continue;
            },
            Key::Ctrl(12) => { draw_screen(&mut editor); continue; },
            _ => {}
        }

        if editor.help {
            editor.help=false;
            editor.status_msg="Ctrl-? for help".to_string();
            draw_screen(&mut editor);
            continue;
        }

        editor.quit_times=0;

        if let Some(prompt) = editor.prompt.take() {
            match prompt {
                Prompt::Save(mut input, mut cx) => {
                    match key {
                        Key::Esc | Key::Ctrl(7) => { editor.status_msg="Canceled".to_string(); editor.prompt=None; draw_screen(&mut editor); continue; },
                        Key::Char(ch) => {
                            if ch=='\r' || ch=='\n' {
                                if input.is_empty() { editor.status_msg="Canceled".to_string(); editor.prompt=None; draw_screen(&mut editor); continue; }
                                let cur = editor.cur_buf;
                                editor.buffers[cur].filename = Some(input.clone());
                                let rows = editor.buffers[cur].rows.clone();
                                let mut content=String::new();
                                for row in &rows { content.push_str(row); content.push('\n'); }
                                if rows.is_empty() { content.clear(); }
                                match fs::write(&input, content.as_bytes()) {
                                    Ok(()) => { editor.buffers[cur].dirty=false; editor.status_msg=format!("{} bytes written to {}", content.len(), input); editor.prompt=None; draw_screen(&mut editor); },
                                    Err(e) => { editor.status_msg=format!("Can't save! {}", e); editor.prompt=Some(Prompt::Save(input, cx)); draw_screen(&mut editor); }
                                }
                                continue;
                            } else {
                                input.insert(cx, ch);
                                cx+=1;
                                editor.prompt=Some(Prompt::Save(input, cx));
                                draw_screen(&mut editor);
                                continue;
                            }
                        },
                        Key::Ctrl(13) => {
                            if input.is_empty() { editor.status_msg="Canceled".to_string(); editor.prompt=None; draw_screen(&mut editor); continue; }
                            let cur = editor.cur_buf;
                            editor.buffers[cur].filename = Some(input.clone());
                            let rows = editor.buffers[cur].rows.clone();
                            let mut content=String::new();
                            for row in &rows { content.push_str(row); content.push('\n'); }
                            if rows.is_empty() { content.clear(); }
                            match fs::write(&input, content.as_bytes()) {
                                Ok(()) => { editor.buffers[cur].dirty=false; editor.status_msg=format!("{} bytes written to {}", content.len(), input); editor.prompt=None; draw_screen(&mut editor); },
                                Err(e) => { editor.status_msg=format!("Can't save! {}", e); editor.prompt=Some(Prompt::Save(input, cx)); draw_screen(&mut editor); }
                            }
                            continue;
                        },
                        Key::Backspace | Key::Ctrl(8) => { if cx>0 { input.remove(cx-1); cx-=1; } editor.prompt=Some(Prompt::Save(input, cx)); draw_screen(&mut editor); continue; },
                        Key::Delete | Key::Ctrl(4) => { if cx<input.len() { input.remove(cx); } editor.prompt=Some(Prompt::Save(input, cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(2) | Key::ArrowLeft => { if cx>0 { cx-=1; } editor.prompt=Some(Prompt::Save(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(6) | Key::ArrowRight => { if cx<input.len() { cx+=1; } editor.prompt=Some(Prompt::Save(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(1) | Key::Home => { cx=0; editor.prompt=Some(Prompt::Save(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(5) | Key::End => { cx=input.len(); editor.prompt=Some(Prompt::Save(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(11) => { input.truncate(cx); editor.prompt=Some(Prompt::Save(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(10) => { input.drain(0..cx); cx=0; editor.prompt=Some(Prompt::Save(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(23) => { if cx>0 { let mut start=cx; while start>0 && input[..start].chars().last().map(|c| c.is_whitespace()).unwrap_or(false) { start-=1; } while start>0 && !input[..start].chars().last().map(|c| c.is_whitespace()).unwrap_or(true) { start-=1; } input.drain(start..cx); cx=start; } editor.prompt=Some(Prompt::Save(input,cx)); draw_screen(&mut editor); continue; },
                        _ => { editor.prompt=Some(Prompt::Save(input,cx)); draw_screen(&mut editor); continue; }
                    }
                },
                Prompt::Open(mut input, mut cx) => {
                    match key {
                        Key::Esc | Key::Ctrl(7) => { editor.status_msg="Canceled".to_string(); editor.prompt=None; draw_screen(&mut editor); continue; },
                        Key::Char(ch) => {
                            if ch=='\r' || ch=='\n' {
                                if input.is_empty() {
                                    editor.buffers.push(Buffer::new(None, vec![String::new()]));
                                    editor.cur_buf = editor.buffers.len()-1;
                                    editor.prompt=None;
                                    editor.status_msg="Ctrl-? for help".to_string();
                                    draw_screen(&mut editor);
                                    continue;
                                }
                                let path = std::path::Path::new(&input);
                                if path.is_dir() {
                                    editor.status_msg=format!("{}: Is a directory", input);
                                    editor.prompt=Some(Prompt::Open(input,cx));
                                    draw_screen(&mut editor);
                                    continue;
                                }
                                if !path.exists() {
                                    editor.buffers.push(Buffer::new(Some(input.clone()), vec![String::new()]));
                                    editor.cur_buf = editor.buffers.len()-1;
                                    editor.prompt=None;
                                    draw_screen(&mut editor);
                                    continue;
                                }
                                match read_file_rows(&input) {
                                    Ok(rows) => { editor.buffers.push(Buffer::new(Some(input.clone()), rows)); editor.cur_buf = editor.buffers.len()-1; editor.prompt=None; draw_screen(&mut editor); },
                                    Err(e) => { editor.status_msg=format!("{}: {}", input, e); editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); }
                                }
                                continue;
                            } else {
                                input.insert(cx, ch);
                                cx+=1;
                                editor.prompt=Some(Prompt::Open(input,cx));
                                draw_screen(&mut editor);
                                continue;
                            }
                        },
                        Key::Ctrl(13) => {
                            if input.is_empty() {
                                editor.buffers.push(Buffer::new(None, vec![String::new()]));
                                editor.cur_buf = editor.buffers.len()-1;
                                editor.prompt=None;
                                editor.status_msg="Ctrl-? for help".to_string();
                                draw_screen(&mut editor);
                                continue;
                            }
                            let path = std::path::Path::new(&input);
                            if path.is_dir() {
                                editor.status_msg=format!("{}: Is a directory", input);
                                editor.prompt=Some(Prompt::Open(input,cx));
                                draw_screen(&mut editor);
                                continue;
                            }
                            if !path.exists() {
                                editor.buffers.push(Buffer::new(Some(input.clone()), vec![String::new()]));
                                editor.cur_buf = editor.buffers.len()-1;
                                editor.prompt=None;
                                draw_screen(&mut editor);
                                continue;
                            }
                            match read_file_rows(&input) {
                                Ok(rows) => { editor.buffers.push(Buffer::new(Some(input.clone()), rows)); editor.cur_buf = editor.buffers.len()-1; editor.prompt=None; draw_screen(&mut editor); },
                                Err(e) => { editor.status_msg=format!("{}: {}", input, e); editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); }
                            }
                            continue;
                        },
                        Key::Backspace | Key::Ctrl(8) => { if cx>0 { input.remove(cx-1); cx-=1; } editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Delete | Key::Ctrl(4) => { if cx<input.len() { input.remove(cx); } editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(2) | Key::ArrowLeft => { if cx>0 { cx-=1; } editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(6) | Key::ArrowRight => { if cx<input.len() { cx+=1; } editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(1) | Key::Home => { cx=0; editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(5) | Key::End => { cx=input.len(); editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(11) => { input.truncate(cx); editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(10) => { input.drain(0..cx); cx=0; editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        Key::Ctrl(23) => { if cx>0 { let mut start=cx; while start>0 && input[..start].chars().last().map(|c| c.is_whitespace()).unwrap_or(false) { start-=1; } while start>0 && !input[..start].chars().last().map(|c| c.is_whitespace()).unwrap_or(true) { start-=1; } input.drain(start..cx); cx=start; } editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; },
                        _ => { editor.prompt=Some(Prompt::Open(input,cx)); draw_screen(&mut editor); continue; }
                    }
                },
                Prompt::Search(mut input, mut cx) => {
                    match key {
                        Key::Esc | Key::Ctrl(7) => {
                            editor.searching=false;
                            editor.search_query.clear();
                            editor.search_matches.clear();
                            editor.status_msg="Canceled".to_string();
                            editor.prompt=None;
                            draw_screen(&mut editor);
                            continue;
                        },
                        Key::Char(ch) => {
                            if ch=='\r' || ch=='\n' {
                                editor.status_msg = if editor.search_matches.is_empty() { "Not found".to_string() } else { "Found".to_string() };
                                editor.searching=false;
                                editor.prompt=None;
                                draw_screen(&mut editor);
                                continue;
                            } else { input.insert(cx, ch); cx+=1; }
                        },
                        Key::Ctrl(13) => {
                            editor.status_msg = if editor.search_matches.is_empty() { "Not found".to_string() } else { "Found".to_string() };
                            editor.searching=false;
                            editor.prompt=None;
                            draw_screen(&mut editor);
                            continue;
                        },
                        Key::Backspace | Key::Ctrl(8) => { if cx>0 { input.remove(cx-1); cx-=1; } },
                        Key::Delete | Key::Ctrl(4) => { if cx<input.len() { input.remove(cx); } },
                        Key::Ctrl(2) | Key::ArrowLeft => { if cx>0 { cx-=1; } },
                        Key::Ctrl(6) | Key::ArrowRight => { if cx<input.len() { cx+=1; } },
                        Key::Ctrl(1) | Key::Home => { cx=0; },
                        Key::Ctrl(5) | Key::End => { cx=input.len(); },
                        Key::Ctrl(11) => { input.truncate(cx); },
                        Key::Ctrl(10) => { input.drain(0..cx); cx=0; },
                        Key::Ctrl(23) => { if cx>0 { let mut start=cx; while start>0 && input[..start].chars().last().map(|c| c.is_whitespace()).unwrap_or(false) { start-=1; } while start>0 && !input[..start].chars().last().map(|c| c.is_whitespace()).unwrap_or(true) { start-=1; } input.drain(start..cx); cx=start; } },
                        Key::Ctrl(16) | Key::ArrowUp => {
                            if !editor.search_matches.is_empty() {
                                if editor.search_idx==0 { editor.search_idx=editor.search_matches.len()-1; } else { editor.search_idx-=1; }
                                let (r,c) = editor.search_matches[editor.search_idx];
                                editor.buffers[editor.cur_buf].cy=r;
                                editor.buffers[editor.cur_buf].cx=c;
                            }
                        },
                        Key::Ctrl(14) | Key::ArrowDown => {
                            if !editor.search_matches.is_empty() {
                                editor.search_idx = (editor.search_idx+1) % editor.search_matches.len();
                                let (r,c) = editor.search_matches[editor.search_idx];
                                editor.buffers[editor.cur_buf].cy=r;
                                editor.buffers[editor.cur_buf].cx=c;
                            }
                        },
                        _ => {},
                    }
                    editor.search_query = input.clone();
                    editor.search_matches.clear();
                    if !editor.search_query.is_empty() {
                        for (r_idx, row) in editor.buffers[editor.cur_buf].rows.iter().enumerate() {
                            let mut start=0;
                            while let Some(pos) = row[start..].find(&editor.search_query) {
                                let abs = start+pos;
                                editor.search_matches.push((r_idx, abs));
                                start = abs + editor.search_query.len();
                                if start >= row.len() { break; }
                            }
                        }
                        if !editor.search_matches.is_empty() && editor.search_idx >= editor.search_matches.len() { editor.search_idx=0; }
                    }
                    editor.prompt=Some(Prompt::Search(input, cx));
                    editor.searching=true;
                    draw_screen(&mut editor);
                    continue;
                }
            }
        }

        match key {
            Key::Ctrl(19) => {
                let cur = editor.cur_buf;
                if editor.buffers[cur].filename.is_none() {
                    editor.prompt=Some(Prompt::Save(String::new(),0));
                    draw_screen(&mut editor);
                } else {
                    let fname = editor.buffers[cur].filename.clone().unwrap();
                    let rows = editor.buffers[cur].rows.clone();
                    let mut content=String::new();
                    for row in &rows { content.push_str(row); content.push('\n'); }
                    if rows.is_empty() { content.clear(); }
                    match fs::write(&fname, content.as_bytes()) {
                        Ok(()) => { editor.buffers[cur].dirty=false; editor.status_msg=format!("{} bytes written to {}", content.len(), fname); },
                        Err(e) => { editor.status_msg=format!("Can't save! {}", e); }
                    }
                    draw_screen(&mut editor);
                }
            },
            Key::Ctrl(15) => { editor.prompt=Some(Prompt::Open(String::new(),0)); draw_screen(&mut editor); },
            Key::Ctrl(24) => {
                if editor.buffers.len()>1 {
                    editor.cur_buf = (editor.cur_buf+1) % editor.buffers.len();
                    draw_screen(&mut editor);
                }
            },
            Key::Alt('x') => {
                if editor.buffers.len()>1 {
                    if editor.cur_buf==0 { editor.cur_buf = editor.buffers.len()-1; } else { editor.cur_buf-=1; }
                    draw_screen(&mut editor);
                }
            },
            Key::Ctrl(7) => {
                editor.prompt=Some(Prompt::Search(String::new(),0));
                editor.search_query.clear();
                editor.search_matches.clear();
                editor.searching=true;
                editor.search_idx=0;
                draw_screen(&mut editor);
            },
            Key::Ctrl(1) | Key::Home => { editor.buffers[editor.cur_buf].cx=0; draw_screen(&mut editor); },
            Key::Ctrl(5) | Key::End => {
                let cur=editor.cur_buf;
                let row_len = editor.buffers[cur].rows.get(editor.buffers[cur].cy).map(|r| r.chars().count()).unwrap_or(0);
                editor.buffers[cur].cx=row_len;
                draw_screen(&mut editor);
            },
            Key::ArrowLeft | Key::Ctrl(2) => {
                let cur=editor.cur_buf;
                if editor.buffers[cur].cx>0 { editor.buffers[cur].cx-=1; }
                else if editor.buffers[cur].cy>0 {
                    editor.buffers[cur].cy-=1;
                    let prev_len = editor.buffers[cur].rows.get(editor.buffers[cur].cy).map(|r| r.chars().count()).unwrap_or(0);
                    editor.buffers[cur].cx=prev_len;
                }
                draw_screen(&mut editor);
            },
            Key::ArrowRight | Key::Ctrl(6) => {
                let cur=editor.cur_buf;
                let row_len = editor.buffers[cur].rows.get(editor.buffers[cur].cy).map(|r| r.chars().count()).unwrap_or(0);
                if editor.buffers[cur].cx < row_len { editor.buffers[cur].cx+=1; }
                else if editor.buffers[cur].cy+1 < editor.buffers[cur].rows.len() {
                    editor.buffers[cur].cy+=1;
                    editor.buffers[cur].cx=0;
                }
                draw_screen(&mut editor);
            },
            Key::ArrowUp | Key::Ctrl(16) => {
                let cur=editor.cur_buf;
                if editor.buffers[cur].cy>0 { editor.buffers[cur].cy-=1; }
