# Test TUI quickly again
python3 - << 'PY'
import pty, os, time, select, struct, fcntl, termios, signal, tempfile

def run_with_pty(argv, inputs=None, width=80, height=24, timeout=3):
    pid, fd = pty.fork()
    if pid==0:
        try:
            winsz=struct.pack("HHHH", height, width,0,0)
            fcntl.ioctl(pty.STDOUT_FILENO, termios.TIOCSWINSZ, winsz)
        except:
            pass
        os.execvp(argv[0], argv)
    else:
        out=b""
        start=time.time()
        idx=0
        next_t=time.time()+(inputs[0][0] if inputs else 999)
        while time.time()-start<timeout:
            now=time.time()
            if inputs and idx < len(inputs) and now>=next_t:
                while True:
                    r,_,_=select.select([fd],[],[],0.02)
                    if not r:
                        break
                    try:
                        chunk=os.read(fd,8192)
                        if not chunk:
                            break
                        out+=chunk
                    except:
                        break
                try:
                    os.write(fd, inputs[idx][1])
                except:
                    break
                idx+=1
                if idx < len(inputs):
                    next_t=now+inputs[idx][0]
                else:
                    next_t=float('inf')
            r,_,_=select.select([fd],[],[],0.1)
            if r:
                try:
                    chunk=os.read(fd,8192)
                    out+=chunk
                except:
                    break
            try:
                pid2,_=os.waitpid(pid,os.WNOHANG)
                if pid2!=0:
                    break
            except:
                break
        try:
            os.kill(pid, signal.SIGKILL)
        except:
            pass
        try:
            os.waitpid(pid,0)
        except:
            pass
        try:
            os.close(fd)
        except:
            pass
        return out

out = run_with_pty(["/workspace/executable"], inputs=[(0.5, b'\x11')], width=80, height=24)
print("empty quit ok" if b"Kiro editor" in out else "fail")
print(out.decode('utf-8', errors='ignore').replace('\x1b','<ESC>')[:1000])

fd, path = tempfile.mkstemp(suffix='.rs')
os.write(fd, b"fn main() { let x = 5; }\n")
os.close(fd)
out = run_with_pty(["/workspace/executable", path], inputs=[(0.5, b'\x11')], width=80, height=24)
print("rust file", out.decode('utf-8', errors='ignore').replace('\x1b','<ESC>')[:1000])
os.unlink(path)
PY
